import { defineConfig } from 'vite'

export default defineConfig({
  base: './',
  build: {
    target: 'es2020',
    assetsInlineLimit: 4096,
    chunkSizeWarningLimit: 1000,
  },
  server: {
    host: '0.0.0.0',
    port: 3000,
  },
})

/* ==========================================================================
   LOST SIGNAL: OUTPOST 09 — interface
   ========================================================================== */
:root {
  --bg: #03070b;
  --bg-deep: #010305;
  --panel: rgba(5, 15, 22, 0.78);
  --panel-solid: #061018;
  --line: rgba(103, 224, 245, 0.22);
  --line-strong: rgba(103, 224, 245, 0.55);
  --cyan: #6ce8ff;
  --cyan-soft: #3cb3c9;
  --cyan-dim: #1b6473;
  --orange: #ffa14d;
  --orange-hot: #ff7a1a;
  --red: #ff5a55;
  --green: #7df0b8;
  --text: #d6edf2;
  --muted: #77919a;
  --font-display: "Bahnschrift", "DIN Alternate", "Arial Narrow", "Segoe UI", sans-serif;
  --font-mono: "SFMono-Regular", "Cascadia Mono", "Roboto Mono", "Courier New", monospace;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--bg-deep);
  color: var(--text);
  font-family: var(--font-display);
  -webkit-tap-highlight-color: transparent;
  user-select: none;
}

button { font-family: inherit; }

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  background: radial-gradient(circle at 50% 60%, #071722 0%, #020509 70%);
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
  touch-action: none;
}

.hidden { display: none !important; }

/* ==========================================================================
   In-game HUD
   ========================================================================== */
.hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 10;
  opacity: 1;
  transition: opacity 0.4s ease;
}
.hud.hud-off { opacity: 0; }

.fx-vignette {
  position: absolute; inset: 0;
  background:
    radial-gradient(ellipse at 50% 48%, transparent 42%, rgba(0, 4, 8, 0.28) 78%, rgba(0, 2, 4, 0.72) 100%),
    linear-gradient(to bottom, rgba(0, 6, 10, 0.35), transparent 18%, transparent 82%, rgba(0, 6, 10, 0.45));
  pointer-events: none;
}
.fx-scanlines {
  position: absolute; inset: 0;
  background: repeating-linear-gradient(to bottom, rgba(140, 245, 255, 0.022) 0px, rgba(140, 245, 255, 0.022) 1px, transparent 1px, transparent 3px);
  mix-blend-mode: screen;
  opacity: 0.7;
  pointer-events: none;
}
.fx-grain {
  position: absolute; inset: -20%;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.5'/%3E%3C/svg%3E");
  opacity: 0.035;
  pointer-events: none;
}

.hud-top-left {
  position: absolute;
  top: max(18px, env(safe-area-inset-top));
  left: max(18px, env(safe-area-inset-left));
  display: flex;
  flex-direction: column;
  gap: 10px;
  width: min(340px, 32vw);
}
.brand {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 10px;
  letter-spacing: 0.22em;
  color: var(--muted);
  font-family: var(--font-mono);
  text-transform: uppercase;
}
.brand-glyph {
  width: 9px; height: 9px;
  border: 1px solid var(--cyan);
  transform: rotate(45deg);
  box-shadow: 0 0 10px rgba(108, 232, 255, 0.6);
}
.brand-sub { color: var(--cyan-dim); letter-spacing: 0.12em; }

.objective-card {
  position: relative;
  background: linear-gradient(135deg, rgba(5, 18, 26, 0.88), rgba(4, 12, 18, 0.68));
  border: 1px solid var(--line);
  border-left: 2px solid var(--cyan);
  padding: 12px 14px 11px;
  clip-path: polygon(0 0, calc(100% - 14px) 0, 100% 14px, 100% 100%, 0 100%);
  backdrop-filter: blur(5px);
  box-shadow: inset 0 0 30px rgba(24, 102, 118, 0.08);
}
.obj-head {
  display: flex; align-items: center; gap: 7px;
  font-family: var(--font-mono);
  font-size: 9px; letter-spacing: 0.22em;
  color: var(--cyan-soft);
}
.pulse-dot {
  width: 6px; height: 6px; border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 8px var(--cyan);
  animation: pulse 2.2s ease-in-out infinite;
}
.pulse-dot.amber { background: var(--orange); box-shadow: 0 0 9px var(--orange); }
@keyframes pulse { 0%, 100% { opacity: 0.45; transform: scale(0.8); } 50% { opacity: 1; transform: scale(1.15); } }

.obj-text {
  margin-top: 7px;
  font-size: 17px;
  line-height: 1.15;
  letter-spacing: 0.03em;
  color: #eafaff;
  text-shadow: 0 0 18px rgba(108, 232, 255, 0.18);
}
.obj-row {
  display: flex; justify-content: space-between; align-items: baseline;
