}
.panel-notch { position: absolute; top: 0; right: 0; width: 25px; height: 25px; border-top: 1px solid var(--cyan); border-right: 1px solid var(--cyan); opacity: .5; }

.hud-top-right {
  position: absolute;
  top: max(18px, env(safe-area-inset-top));
