  width: min(250px, 28vw);
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 8px;
}
.status-panel {
  width: 100%;
  background: linear-gradient(135deg, rgba(4, 14, 21, 0.88), rgba(4, 12, 18, 0.6));
  border: 1px solid var(--line);
