  margin-bottom: 10px;
}
.signal-ok { color: var(--green); }
.signal-warn { color: var(--orange); animation: pulse 1.1s infinite; }
.signal-bad { color: var(--red); animation: pulse 0.55s infinite; }
.stat { margin-bottom: 7px; }
.stat-label {
  display: flex; justify-content: space-between;
  font-family: var(--font-mono);
  font-size: 8.5px; letter-spacing: 0.15em;
  color: var(--muted);
  margin-bottom: 3px;
}
.stat-label b { color: var(--text); font-size: 10px; font-weight: 500; }
.bar { height: 4px; background: rgba(255, 255, 255, 0.07); overflow: hidden; }
.bar i {
  display: block; height: 100%; width: 100%;
  transform-origin: left center;
  transition: transform 0.22s ease;
}
.bar-health { background: linear-gradient(90deg, #a83232, var(--red)); box-shadow: 0 0 8px rgba(255, 90, 85, 0.5); }
.bar-energy { background: linear-gradient(90deg, #1b7a8c, var(--cyan)); box-shadow: 0 0 8px rgba(108, 232, 255, 0.45); }
.bar-battery { background: linear-gradient(90deg, #92591e, var(--orange)); box-shadow: 0 0 8px rgba(255, 161, 77, 0.45); }
.threat-line {
  display: flex; align-items: center; gap: 7px;
  padding-top: 8px; margin-top: 8px;
  border-top: 1px solid rgba(108, 232, 255, 0.1);
  font-family: var(--font-mono);
  font-size: 8px; letter-spacing: 0.12em;
  color: var(--muted);
}
.threat-dot { width: 5px; height: 5px; border-radius: 50%; background: var(--green); box-shadow: 0 0 7px var(--green); }
.threat-dot.warn { background: var(--orange); box-shadow: 0 0 8px var(--orange); }
.threat-dot.alert { background: var(--red); box-shadow: 0 0 10px var(--red); animation: pulse 0.55s infinite; }

.hud-buttons { display: flex; gap: 6px; pointer-events: auto; }
.hud-icon-btn {
  width: 35px; height: 32px;
  display: grid; place-items: center;
  background: rgba(5, 18, 25, 0.8);
  border: 1px solid var(--line);
  color: var(--cyan-soft);
  cursor: pointer;
  clip-path: polygon(6px 0, 100% 0, 100% calc(100% - 6px), calc(100% - 6px) 100%, 0 100%, 0 6px);
  transition: all .18s ease;
}
.hud-icon-btn svg { width: 14px; height: 14px; fill: currentColor; }
.hud-icon-btn:hover, .hud-icon-btn.active { color: var(--cyan); border-color: var(--line-strong); background: rgba(18, 62, 75, 0.85); box-shadow: 0 0 16px rgba(108, 232, 255, 0.18); }

.quickbar {
  position: absolute;
  right: max(18px, env(safe-area-inset-right));
  bottom: max(18px, env(safe-area-inset-bottom));
  width: 250px;
  background: linear-gradient(135deg, rgba(4, 14, 21, 0.82), rgba(3, 10, 15, 0.55));
  border: 1px solid rgba(108, 232, 255, 0.16);
  padding: 9px;
  clip-path: polygon(10px 0, 100% 0, 100% 100%, 0 100%, 0 10px);
  pointer-events: auto;
}
.quickbar-head {
  display: flex; justify-content: space-between;
  font-family: var(--font-mono);
  font-size: 8px; letter-spacing: 0.18em;
  color: var(--muted);
  margin-bottom: 7px;
}
.quickbar-head span:last-child { color: var(--cyan); }
.quick-slots { display: grid; grid-template-columns: repeat(6, 1fr); gap: 4px; }
.quick-slot {
  aspect-ratio: 1;
  border: 1px solid rgba(108, 232, 255, 0.14);
