.quick-slot.empty::after {
  content: ""; width: 5px; height: 5px;
  border: 1px solid rgba(108, 232, 255, 0.16);
  transform: rotate(45deg);
}
.quick-slot.filled { border-color: rgba(108, 232, 255, 0.4); }
.quick-slot.filled:hover { background: rgba(23, 65, 78, 0.75); border-color: var(--cyan); }
.quick-slot .slot-glyph { width: 74%; height: 74%; display: grid; place-items: center; }
.quick-slot .slot-glyph svg { width: 100%; height: 100%; }
.quick-slot .slot-rarity {
