.quick-slot.r-uncommon .slot-rarity { background: var(--green); }
.quick-slot.r-rare .slot-rarity { background: var(--cyan); }
.quick-slot.r-legendary .slot-rarity { background: var(--orange); box-shadow: 0 0 8px var(--orange); }
