.extract-bar { height: 5px; background: rgba(255, 161, 77, 0.12); margin: 8px 0 6px; overflow: hidden; }
.extract-bar i { display: block; height: 100%; width: 0; background: linear-gradient(90deg, #a44f0f, var(--orange), #ffe1a7); box-shadow: 0 0 12px var(--orange); transition: width .1s linear; }
