.objective-marker.show { opacity: .9; }
.marker-diamond {
  width: 10px; height: 10px;
  border: 1px solid var(--cyan);
  transform: rotate(45deg);
  box-shadow: 0 0 8px rgba(108, 232, 255, .4);
  animation: markerPulse 2.4s ease-in-out infinite;
}
@keyframes markerPulse { 0%,100% { transform: rotate(45deg) scale(.75); opacity:.55 } 50% { transform: rotate(45deg) scale(1.05); opacity:1 } }
#marker-dist { color: rgba(214,237,242,.65); }

.toast-stack {
  position: absolute;
  top: 120px; right: max(18px, env(safe-area-inset-right));
  width: min(300px, 34vw);
  display: flex; flex-direction: column; gap: 6px;
  align-items: stretch;
  z-index: 6;
}
.toast {
  position: relative;
  padding: 8px 10px 8px 12px;
  background: rgba(4, 16, 22, 0.92);
  border: 1px solid rgba(108, 232, 255, 0.22);
  border-left: 2px solid var(--cyan);
  font-family: var(--font-mono);
  font-size: 9px; letter-spacing: .05em;
  color: var(--text);
  animation: toastIn .28s ease both;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 7px), calc(100% - 7px) 100%, 0 100%);
  backdrop-filter: blur(4px);
}
.toast.out { animation: toastOut .3s ease both; }
.toast b { display: block; color: var(--cyan); font-size: 10px; letter-spacing: .12em; margin-bottom: 3px; font-weight: 600; }
.toast .t-sub { color: var(--muted); font-size: 8px; letter-spacing: .08em; }
.toast.r-common { border-left-color: #8fa3a8; }
.toast.r-common b { color: #b8c8cc; }
.toast.r-uncommon { border-left-color: var(--green); }
.toast.r-uncommon b { color: var(--green); }
.toast.r-rare { border-left-color: var(--cyan); }
.toast.r-rare b { color: var(--cyan); }
.toast.r-legendary { border-left-color: var(--orange); background: rgba(28, 17, 7, 0.92); }
.toast.r-legendary b { color: var(--orange); }
.toast.r-warn { border-left-color: var(--red); background: rgba(30, 8, 8, 0.9); }
.toast.r-warn b { color: var(--red); }
.toast.r-good { border-left-color: var(--green); }
.toast.r-good b { color: var(--green); }
@keyframes toastIn { from { opacity: 0; transform: translateX(18px); } to { opacity: 1; transform: translateX(0); } }
@keyframes toastOut { to { opacity: 0; transform: translateX(18px); } }

.damage-vignette {
  position: absolute; inset: 0;
  background: radial-gradient(ellipse at center, transparent 35%, rgba(255, 30, 30, 0.35) 100%);
  opacity: 0;
  pointer-events: none;
  transition: opacity .4s;
}
.damage-vignette.hit { opacity: 1; transition: opacity .05s; }

.desktop-hint {
  position: absolute;
  left: max(18px, env(safe-area-inset-left));
  bottom: max(20px, env(safe-area-inset-bottom));
  display: flex; gap: 12px;
  font-family: var(--font-mono);
  font-size: 8px; letter-spacing: .1em;
  color: rgba(119, 145, 154, .75);
  pointer-events: none;
}

/* ==========================================================================
   Mobile controls
   ========================================================================== */
.mobile-controls { position: absolute; inset: 0; z-index: 20; pointer-events: none; display: none; }
body.is-mobile .mobile-controls { display: block; }
body.is-mobile .desktop-hint { display: none; }
body.is-mobile .quickbar { display: none; }
body.is-mobile .hud-top-left { width: 47vw; max-width: 330px; top: max(10px, env(safe-area-inset-top)); left: max(10px, env(safe-area-inset-left)); }
body.is-mobile .brand { display: none; }
body.is-mobile .objective-card { padding: 8px 10px; }
body.is-mobile .obj-text { font-size: 13px; margin-top: 4px; }
body.is-mobile .obj-row { font-size: 7.5px; margin-top: 4px; }
body.is-mobile .hud-top-right { width: 42vw; max-width: 240px; top: max(10px, env(safe-area-inset-top)); right: max(10px, env(safe-area-inset-right)); }
body.is-mobile .status-panel { padding: 8px 9px; }
body.is-mobile .status-title { font-size: 7px; margin-bottom: 6px; }
body.is-mobile .stat { margin-bottom: 5px; }
body.is-mobile .stat-label { font-size: 7px; }
body.is-mobile .threat-line { font-size: 6.5px; padding-top: 5px; margin-top: 5px; }
body.is-mobile .hud-buttons { display: none; }
body.is-mobile .toast-stack { top: 120px; width: 58vw; max-width: 300px; right: 10px; }
body.is-mobile .toast { font-size: 8px; }
body.is-mobile .interact-prompt { bottom: calc(178px + env(safe-area-inset-bottom)); font-size: 11px; max-width: 86vw; }
body.is-mobile .extract-panel { top: auto; bottom: calc(185px + env(safe-area-inset-bottom)); width: 74vw; }
body.is-mobile .hidden-indicator { top: 45%; }

.joystick {
  position: absolute;
  left: max(18px, env(safe-area-inset-left));
  bottom: calc(24px + env(safe-area-inset-bottom));
  width: 118px; height: 118px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(15, 48, 58, 0.28), rgba(3, 12, 17, 0.38));
  border: 1px solid rgba(108, 232, 255, 0.22);
  box-shadow: inset 0 0 30px rgba(108, 232, 255, 0.06);
  pointer-events: auto;
  touch-action: none;
}
.joystick-ring { position: absolute; inset: 18px; border: 1px solid rgba(108, 232, 255, 0.12); border-radius: 50%; }
.joystick-stick {
  position: absolute; left: 50%; top: 50%;
  width: 48px; height: 48px; margin: -24px 0 0 -24px;
  border-radius: 50%;
  background: radial-gradient(circle at 40% 35%, rgba(108, 232, 255, 0.35), rgba(6, 25, 33, 0.9));
  border: 1px solid rgba(108, 232, 255, 0.55);
  box-shadow: 0 0 18px rgba(108, 232, 255, 0.15);
  transition: transform .05s linear;
}
.mobile-actions {
  position: absolute;
  right: max(16px, env(safe-area-inset-right));
  bottom: calc(22px + env(safe-area-inset-bottom));
  display: grid;
  grid-template-columns: 64px 64px;
  grid-template-rows: 64px 64px;
  gap: 9px;
  pointer-events: auto;
}
.touch-btn {
  border-radius: 50%;
  border: 1px solid rgba(108, 232, 255, 0.38);
  background: radial-gradient(circle at 40% 35%, rgba(23, 65, 78, 0.75), rgba(4, 14, 20, 0.9));
  color: var(--cyan);
  font-family: var(--font-mono);
  font-size: 8px;
  letter-spacing: .08em;
  display: grid; place-items: center;
  touch-action: none;
  box-shadow: inset 0 0 14px rgba(108, 232, 255, 0.08);
}
.touch-btn.interact { grid-column: 2; grid-row: 1; width: 66px; height: 66px; border-color: rgba(108, 232, 255, 0.7); box-shadow: 0 0 20px rgba(108, 232, 255, 0.16), inset 0 0 16px rgba(108,232,255,.12); }
.touch-btn.interact.hot { background: radial-gradient(circle, rgba(38, 112, 132, 0.9), rgba(8, 28, 38, 0.95)); color: #eafaff; border-color: #c6f8ff; animation: pulse 1.4s infinite; }
.touch-btn.sprint { grid-column: 1; grid-row: 2; width: 66px; height: 66px; }
.touch-btn.small { width: 46px; height: 46px; font-size: 6.5px; background: rgba(4, 14, 20, 0.8); position: absolute; }
.touch-btn.small:nth-of-type(3) { right: 0; bottom: 154px; }
.touch-btn.small:nth-of-type(4) { right: 54px; bottom: 154px; }
.touch-btn.active { background: radial-gradient(circle, rgba(48, 132, 152, 0.9), rgba(6, 24, 32, 0.95)); border-color: var(--cyan); }
.look-hint {
  position: absolute; right: 22px; bottom: calc(198px + env(safe-area-inset-bottom));
  font-family: var(--font-mono); font-size: 7px; letter-spacing: .12em; color: rgba(119,145,154,.5);
  opacity: 1; transition: opacity .5s;
}
body.has-looked .look-hint { opacity: 0; }

/* ==========================================================================
   Screens & modals
   ========================================================================== */
.screen {
  position: absolute; inset: 0;
  z-index: 40;
  display: flex; align-items: center; justify-content: center;
  background: radial-gradient(ellipse at 50% 50%, rgba(5, 20, 28, 0.5), rgba(1, 4, 7, 0.9));
  backdrop-filter: blur(3px);
  animation: screenIn .3s ease;
}
@keyframes screenIn { from { opacity: 0; } to { opacity: 1; } }

.modal {
  position: relative;
  width: min(540px, 92vw);
  max-height: 88vh;
  overflow: auto;
  background: linear-gradient(145deg, rgba(6, 20, 28, 0.97), rgba(3, 10, 15, 0.98));
  border: 1px solid var(--line);
  padding: 30px 32px 26px;
  box-shadow: 0 30px 100px rgba(0, 0, 0, 0.7), inset 0 0 80px rgba(25, 100, 118, 0.06);
  clip-path: polygon(0 0, calc(100% - 22px) 0, 100% 22px, 100% 100%, 22px 100%, 0 calc(100% - 22px));
}
.modal-corner { position: absolute; width: 18px; height: 18px; border-color: var(--cyan); opacity: .6; pointer-events: none; }
.modal-corner.tl { left: 6px; top: 6px; border-left: 1px solid; border-top: 1px solid; }
.modal-corner.tr { right: 6px; top: 6px; border-right: 1px solid; border-top: 1px solid; }
.modal-corner.bl { left: 6px; bottom: 6px; border-left: 1px solid; border-bottom: 1px solid; }
.modal-corner.br { right: 6px; bottom: 6px; border-right: 1px solid; border-bottom: 1px solid; }
.modal-kicker {
  font-family: var(--font-mono); font-size: 8px; letter-spacing: .24em;
  color: var(--cyan-soft); margin-bottom: 10px;
}
.modal h2 {
  font-size: clamp(30px, 5vw, 46px); line-height: .92; letter-spacing: .02em;
  margin: 0 0 22px; font-weight: 300; color: #eafaff;
  text-transform: uppercase;
}
.modal h2 b { color: var(--cyan); font-weight: 600; }

.primary-btn {
  pointer-events: auto;
  display: inline-flex; align-items: center; justify-content: space-between; gap: 24px;
  min-width: 230px;
  padding: 14px 18px;
  background: linear-gradient(120deg, rgba(28, 111, 130, 0.9), rgba(12, 48, 60, 0.9));
  border: 1px solid rgba(108, 232, 255, 0.6);
  color: #eafaff;
  font-family: var(--font-mono);
  font-size: 11px; letter-spacing: .18em;
  cursor: pointer;
  position: relative;
  clip-path: polygon(0 0, calc(100% - 12px) 0, 100% 12px, 100% 100%, 12px 100%, 0 calc(100% - 12px));
  transition: all .18s ease;
  box-shadow: 0 0 34px rgba(108, 232, 255, 0.08), inset 0 0 24px rgba(108, 232, 255, 0.06);
}
.primary-btn i { font-style: normal; font-size: 17px; color: var(--cyan); }
.primary-btn:hover { background: linear-gradient(120deg, rgba(38, 148, 172, 0.95), rgba(15, 66, 82, 0.95)); box-shadow: 0 0 44px rgba(108, 232, 255, 0.2), inset 0 0 30px rgba(108, 232, 255, 0.1); border-color: var(--cyan); }
.primary-btn:active { transform: translateY(1px); }
.primary-btn.compact { min-width: 190px; padding: 11px 14px; font-size: 10px; }

.ghost-btn {
  pointer-events: auto;
  background: transparent;
  border: 1px solid rgba(108, 232, 255, 0.22);
  color: var(--muted);
  padding: 7px 10px;
  font-family: var(--font-mono);
  font-size: 8px; letter-spacing: .14em;
  cursor: pointer;
  transition: all .18s;
}
.ghost-btn:hover { border-color: var(--cyan); color: var(--cyan); }

/* Title ------------------------------------------------------------------ */
.title-screen {
  z-index: 50;
  background: none;
  backdrop-filter: none;
  align-items: stretch;
  justify-content: stretch;
}
.title-backdrop {
  position: absolute; inset: 0;
  background:
    linear-gradient(90deg, rgba(1, 5, 8, 0.94) 0%, rgba(1, 6, 10, 0.72) 36%, rgba(1, 5, 8, 0.18) 66%, rgba(1, 4, 7, 0.55) 100%),
    linear-gradient(to bottom, rgba(0, 3, 6, 0.55), transparent 30%, transparent 72%, rgba(0, 3, 6, 0.85));
  pointer-events: none;
}
.title-frame {
  position: relative;
  z-index: 2;
  flex: 1;
  display: flex; flex-direction: column;
  padding: 4.5vh 5vw 4vh;
  max-width: 1600px;
  margin: 0 auto;
  width: 100%;
}
.title-topline {
  display: flex; justify-content: space-between; align-items: center;
  font-family: var(--font-mono); font-size: 8px; letter-spacing: .2em;
  color: rgba(119, 145, 154, .66);
  padding-bottom: 12px;
  border-bottom: 1px solid rgba(108, 232, 255, 0.12);
}
.title-topline span:nth-child(2) { color: var(--cyan-dim); }
.title-main {
  margin-top: auto;
  padding-bottom: 4vh;
  width: min(640px, 60vw);
}
.title-kicker {
  display: flex; align-items: center; gap: 8px;
  font-family: var(--font-mono); font-size: 9px; letter-spacing: .2em;
  color: var(--cyan-soft);
  margin-bottom: 16px;
}
#title-clock { color: var(--muted); margin-left: 8px; }
.title-main h1 {
  position: relative;
  margin: 0;
  font-size: clamp(60px, 10vw, 132px);
  line-height: .82;
  font-weight: 700;
  letter-spacing: .015em;
  color: #f2fbff;
  text-transform: uppercase;
  text-shadow: 0 0 70px rgba(108, 232, 255, 0.2), 0 4px 30px rgba(0,0,0,.8);
}
.title-main h1 span {
  display: block;
  color: transparent;
  -webkit-text-stroke: 1px rgba(108, 232, 255, 0.55);
  text-shadow: 0 0 40px rgba(108, 232, 255, 0.12);
}
.title-outpost {
  display: flex; align-items: center; gap: 10px;
  margin-top: 18px;
  font-family: var(--font-mono); font-size: clamp(12px, 1.4vw, 16px);
  letter-spacing: .42em;
  color: var(--orange);
}
.title-outpost::before, .title-outpost::after {
  content: ""; height: 1px; width: 34px; background: rgba(255, 161, 77, 0.5);
}
.title-outpost b { font-size: 1.4em; letter-spacing: 0; color: var(--orange); text-shadow: 0 0 22px rgba(255, 161, 77, .55); }
.title-tagline {
  margin: 20px 0 26px;
  max-width: 420px;
  font-size: 14px; line-height: 1.55; color: #9bb7bf;
  letter-spacing: .015em;
}
.title-secondary { display: flex; gap: 8px; margin-top: 14px; }
.title-brief {
  position: absolute;
  right: 5vw; bottom: 12vh;
  width: min(330px, 27vw);
  border-left: 1px solid rgba(108, 232, 255, 0.25);
  padding-left: 18px;
  display: flex; flex-direction: column; gap: 16px;
  background: linear-gradient(90deg, rgba(2, 9, 13, 0.35), transparent);
}
.brief-label {
  font-family: var(--font-mono); font-size: 8px; letter-spacing: .22em;
  color: var(--orange); margin-bottom: 5px;
}
.brief-block p {
  margin: 0; font-size: 11px; line-height: 1.55; color: #8fa8b0;
}
.brief-grid {
  display: grid; grid-template-columns: 1fr 1fr;
  gap: 6px 12px;
  padding-top: 12px;
  border-top: 1px solid rgba(108, 232, 255, 0.12);
  font-family: var(--font-mono); font-size: 8px; letter-spacing: .08em; color: var(--muted);
}
.title-footer {
  position: absolute; left: 5vw; right: 5vw; bottom: 3vh;
  display: flex; justify-content: space-between;
  font-family: var(--font-mono); font-size: 7px; letter-spacing: .18em;
  color: rgba(119, 145, 154, 0.45);
  border-top: 1px solid rgba(108, 232, 255, 0.09);
  padding-top: 10px;
}

/* Pause ------------------------------------------------------------------ */
.pause-actions { display: flex; flex-direction: column; gap: 8px; margin: 6px 0 18px; }
.menu-btn {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  width: 100%; padding: 12px 14px;
  background: rgba(10, 32, 42, 0.55);
  border: 1px solid rgba(108, 232, 255, 0.16);
  color: var(--muted);
  font-family: var(--font-mono); font-size: 9px; letter-spacing: .16em;
  cursor: pointer;
  transition: all .18s;
}
.menu-btn:hover { border-color: rgba(108, 232, 255, 0.45); color: var(--cyan); background: rgba(16, 48, 60, 0.7); }
.menu-btn b { color: var(--cyan); font-weight: 500; }
.menu-btn.danger:hover { border-color: rgba(255, 90, 85, 0.55); color: var(--red); background: rgba(40, 12, 12, 0.5); }
.quality-row { cursor: default; }
.quality-row:hover { border-color: rgba(108, 232, 255, 0.16); color: var(--muted); background: rgba(10, 32, 42, 0.55); }
.quality-options { display: flex; gap: 4px; }
.quality-options button {
  padding: 3px 7px;
  font-family: var(--font-mono); font-size: 7.5px; letter-spacing: .08em;
  background: transparent; border: 1px solid rgba(108, 232, 255, 0.18);
  color: var(--muted); cursor: pointer;
}
.quality-options button.active { border-color: var(--cyan); color: var(--cyan); background: rgba(20, 64, 78, 0.7); }
.pause-controls {
  display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 7px;
  padding-top: 14px; border-top: 1px solid rgba(108, 232, 255, 0.1);
  font-family: var(--font-mono); font-size: 8px; color: var(--muted); letter-spacing: .06em;
}
.pause-note { margin-top: 14px; font-family: var(--font-mono); font-size: 7.5px; line-height: 1.5; color: rgba(119, 145, 154, .55); letter-spacing: .05em; }

/* Inventory -------------------------------------------------------------- */
.inventory-modal { width: min(720px, 94vw); }
.inventory-head { display: flex; justify-content: space-between; align-items: flex-end; gap: 16px; flex-wrap: wrap; }
.inventory-head h2 { margin-bottom: 12px; }
.inventory-summary { display: flex; gap: 16px; font-family: var(--font-mono); font-size: 8px; letter-spacing: .12em; color: var(--muted); margin-bottom: 16px; }
.inventory-summary b { color: var(--cyan); font-size: 12px; margin-left: 4px; font-weight: 500; }
.inventory-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin: 8px 0 16px; min-height: 190px; }
.inv-card {
  position: relative;
  border: 1px solid rgba(108, 232, 255, 0.15);
  background: rgba(7, 23, 31, 0.65);
  padding: 10px;
  display: flex; flex-direction: column;
  min-height: 96px;
  clip-path: polygon(0 0, calc(100% - 9px) 0, 100% 9px, 100% 100%, 0 100%);
}
.inv-card.empty {
  border-style: dashed;
  border-color: rgba(108, 232, 255, 0.1);
  background: rgba(5, 15, 20, 0.3);
  align-items: center; justify-content: center;
  color: rgba(119, 145, 154, 0.32);
  font-family: var(--font-mono); font-size: 8px; letter-spacing: .16em;
}
.inv-card.r-uncommon { border-left: 2px solid var(--green); }
.inv-card.r-rare { border-left: 2px solid var(--cyan); }
.inv-card.r-legendary { border-left: 2px solid var(--orange); box-shadow: inset 0 0 30px rgba(255, 161, 77, .04); }
.inv-card.r-common { border-left: 2px solid #8fa3a8; }
.inv-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 8px; }
.inv-icon { width: 34px; height: 34px; opacity: .95; }
.inv-icon svg { width: 100%; height: 100%; }
.inv-rarity { font-family: var(--font-mono); font-size: 6.5px; letter-spacing: .14em; padding: 2px 4px; border: 1px solid currentColor; }
.inv-name { margin: 7px 0 2px; font-size: 12px; letter-spacing: .03em; color: #e2f5f9; line-height: 1.2; }
.inv-desc { font-family: var(--font-mono); font-size: 7px; line-height: 1.45; color: var(--muted); letter-spacing: .02em; flex: 1; }
.inv-bottom { display: flex; justify-content: space-between; align-items: center; margin-top: 8px; padding-top: 6px; border-top: 1px solid rgba(108, 232, 255, 0.08); }
.inv-credits { font-family: var(--font-mono); font-size: 8px; color: var(--cyan); letter-spacing: .08em; }
.inv-tag { font-family: var(--font-mono); font-size: 6.5px; color: var(--orange); letter-spacing: .1em; }
.inv-drop {
  font-family: var(--font-mono); font-size: 6.5px; letter-spacing: .08em;
  background: transparent; border: 1px solid rgba(255, 90, 85, 0.25); color: rgba(255, 120, 110, 0.7);
  padding: 2px 5px; cursor: pointer;
}
.inv-drop:hover { border-color: var(--red); color: var(--red); }
.inventory-footer { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin-top: 12px; padding-top: 14px; border-top: 1px solid rgba(108, 232, 255, 0.1); }
.clearance { font-family: var(--font-mono); font-size: 8px; letter-spacing: .1em; color: var(--muted); }
.clearance b { color: var(--orange); }
.inventory-note { margin-top: 12px; font-family: var(--font-mono); font-size: 7px; color: rgba(119, 145, 154, .55); line-height: 1.5; letter-spacing: .04em; }

/* Log -------------------------------------------------------------------- */
.log-modal { width: min(620px, 92vw); }
.log-body {
  font-family: var(--font-mono);
  font-size: 11px; line-height: 1.75;
  color: #9cb7bf;
  border-left: 1px solid rgba(108, 232, 255, 0.22);
  padding: 2px 0 2px 18px;
  margin-bottom: 22px;
  white-space: pre-wrap;
  max-height: 46vh;
  overflow: auto;
}
.log-body b { color: var(--cyan); font-weight: 500; }
.log-body .warn { color: var(--orange); }

/* Dead / complete -------------------------------------------------------- */
.dead-modal, .complete-modal { width: min(660px, 94vw); }
.dead-sig { font-family: var(--font-mono); font-size: 8px; letter-spacing: .2em; color: var(--red); margin-bottom: 12px; }
.dead-modal p { color: #8fa8b0; font-size: 12px; line-height: 1.5; max-width: 380px; margin: 0 0 24px; }
.dead-modal h2 b { color: var(--red); }
.complete-kicker { display: flex; align-items: center; gap: 8px; font-family: var(--font-mono); font-size: 8px; letter-spacing: .18em; color: var(--green); margin-bottom: 12px; }
.complete-modal h2 b { color: var(--green); }
.complete-stats {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px;
  margin: 18px 0;
}
.complete-stats div {
  border: 1px solid rgba(108, 232, 255, 0.14);
  padding: 10px;
  background: rgba(7, 23, 31, 0.5);
}
