    this.scene = scene
    this.group = new THREE.Group()
    this.model = new THREE.Group()
    this.group.add(this.model)
    this.scene.add(this.group)

    const suit = new THREE.MeshStandardMaterial({ color: 0x18232b, roughness: 0.72, metalness: 0.28 })
    const armor = new THREE.MeshStandardMaterial({ color: 0x2b3c46, roughness: 0.52, metalness: 0.55 })
