    const cyan = new THREE.MeshBasicMaterial({ color: 0x8ff5ff })
    const cyanDim = new THREE.MeshBasicMaterial({ color: 0x38a9bc })
    const orange = new THREE.MeshBasicMaterial({ color: 0xffa14d })
    const visorMat = new THREE.MeshBasicMaterial({ color: 0x74f2ff })
    this.materials = { suit, armor, armorDark, cyan, cyanDim, orange }

    /* torso ----------------------------------------------------------------- */
    const torso = new THREE.Mesh(new THREE.BoxGeometry(0.52, 0.56, 0.32), suit)
    torso.position.y = 1.28
    torso.geometry.translate(0, 0, 0)
    this.model.add(torso)

    const chest = new THREE.Mesh(new THREE.BoxGeometry(0.55, 0.38, 0.12), armor)
    chest.position.set(0, 1.36, 0.18)
    this.model.add(chest)
    const chestStrip = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.025, 0.02), cyan)
    chestStrip.position.set(0, 1.4, 0.25)
    this.model.add(chestStrip)
    const chestStrip2 = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.22, 0.02), cyanDim)
    chestStrip2.position.set(-0.17, 1.31, 0.25)
    this.model.add(chestStrip2)
    const badge = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.06, 0.02), orange)
    badge.position.set(0.16, 1.28, 0.25)
    this.model.add(badge)

    const belt = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.1, 0.34), webbing)
    belt.position.y = 1.0
    this.model.add(belt)
    const beltBuckle = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.07, 0.03), armor)
    beltBuckle.position.set(0, 1.0, 0.18)
    this.model.add(beltBuckle)

    const hips = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.22, 0.3), armorDark)
    hips.position.y = 0.9
    this.model.add(hips)

    /* backpack -------------------------------------------------------------- */
    const pack = new THREE.Mesh(new THREE.BoxGeometry(0.38, 0.48, 0.2), armorDark)
    pack.position.set(0, 1.28, -0.23)
    this.model.add(pack)
    const packTop = new THREE.Mesh(new THREE.BoxGeometry(0.32, 0.1, 0.16), armor)
    packTop.position.set(0, 1.55, -0.22)
    this.model.add(packTop)
    for (const s of [-1, 1]) {
      const tube = new THREE.Mesh(new THREE.CylinderGeometry(0.028, 0.028, 0.5, 6), cyanDim)
      tube.position.set(s * 0.16, 1.28, -0.34)
      this.model.add(tube)
    }
    const packStrip = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.025, 0.02), cyan)
    packStrip.position.set(0, 1.12, -0.34)
    this.model.add(packStrip)

    /* head + helmet --------------------------------------------------------- */
    this.head = new THREE.Group()
    this.head.position.set(0, 1.68, 0)
    this.model.add(this.head)
    const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.12, 0.1, 8), armorDark)
    neck.position.y = -0.15
    this.head.add(neck)
    const helmet = new THREE.Mesh(new THREE.SphereGeometry(0.205, 12, 9), armor)
    helmet.scale.set(1.0, 1.06, 1.02)
    this.head.add(helmet)
    const jaw = new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.12, 0.18), armorDark)
    jaw.position.set(0, -0.08, 0.1)
    this.head.add(jaw)
    const visor = new THREE.Mesh(new THREE.BoxGeometry(0.26, 0.095, 0.045), visorMat)
    visor.position.set(0, 0.02, 0.19)
    this.head.add(visor)
    const visorTop = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.03, 0.03), armorDark)
    visorTop.position.set(0, 0.09, 0.18)
    this.head.add(visorTop)
    for (const s of [-1, 1]) {
      const ear = new THREE.Mesh(new THREE.BoxGeometry(0.055, 0.12, 0.12), armor)
      ear.position.set(s * 0.2, 0.0, 0)
      this.head.add(ear)
      const earLight = new THREE.Mesh(new THREE.BoxGeometry(0.012, 0.035, 0.04), cyan)
      earLight.position.set(s * 0.232, 0.01, 0.04)
      this.head.add(earLight)
    }
    const antenna = new THREE.Mesh(new THREE.CylinderGeometry(0.008, 0.012, 0.22, 5), armorDark)
    antenna.position.set(0.17, 0.22, -0.05)
    antenna.rotation.z = -0.18
    this.head.add(antenna)
    const antennaTip = new THREE.Mesh(new THREE.SphereGeometry(0.022, 6, 5), orange)
    antennaTip.position.set(0.2, 0.33, -0.05)
    this.head.add(antennaTip)
    this.visorGlow = makeSprite(glowTexture(), 0x5fe9ff, 0.55, 0.3)
    this.visorGlow.position.set(0, 0.02, 0.23)
    this.head.add(this.visorGlow)

    /* shoulders + arms ------------------------------------------------------ */
    this.arms = []
    for (const side of [-1, 1]) {
      const pivot = new THREE.Group()
      pivot.position.set(side * 0.34, 1.47, 0)
      this.model.add(pivot)

      const shoulder = new THREE.Mesh(new THREE.SphereGeometry(0.12, 8, 6), armor)
      shoulder.scale.set(1.1, 0.8, 1)
      pivot.add(shoulder)
      const shoulderLight = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.02, 0.14), cyan)
      shoulderLight.position.set(side * 0.03, 0.07, 0.02)
      pivot.add(shoulderLight)

      const upper = capsule(0.075, 0.24, suit, 6)
      upper.position.y = -0.2
      pivot.add(upper)
      const elbow = new THREE.Mesh(new THREE.SphereGeometry(0.075, 6, 5), armorDark)
      elbow.position.y = -0.36
      pivot.add(elbow)
      const fore = capsule(0.065, 0.22, armor, 6)
      fore.position.y = -0.5
      pivot.add(fore)
      const glove = new THREE.Mesh(new THREE.BoxGeometry(0.11, 0.13, 0.13), armorDark)
      glove.position.set(0, -0.66, 0.02)
      pivot.add(glove)
      const cuff = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.025, 0.1), cyanDim)
      cuff.position.set(0, -0.43, 0)
      pivot.add(cuff)
      pivot.rotation.x = side * 0.03
      this.arms.push({ pivot, side })
    }

    /* legs ----------------------------------------------------------------- */
    this.legs = []
    for (const side of [-1, 1]) {
      const pivot = new THREE.Group()
      pivot.position.set(side * 0.145, 0.88, 0)
      this.model.add(pivot)
      const thigh = capsule(0.095, 0.28, suit, 6)
      thigh.position.y = -0.22
      pivot.add(thigh)
      const kneePad = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.14, 0.09), armor)
      kneePad.position.set(0, -0.38, 0.06)
      pivot.add(kneePad)
      const shin = capsule(0.078, 0.28, armorDark, 6)
      shin.position.y = -0.54
      pivot.add(shin)
      const boot = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.14, 0.28), armor)
      boot.position.set(0, -0.75, 0.05)
      pivot.add(boot)
      const bootLight = new THREE.Mesh(new THREE.BoxGeometry(0.09, 0.018, 0.02), cyan)
      bootLight.position.set(0, -0.71, 0.2)
      pivot.add(bootLight)
      const thighStripe = new THREE.Mesh(new THREE.BoxGeometry(0.02, 0.18, 0.06), orange)
      thighStripe.position.set(side * 0.09, -0.2, 0.03)
      pivot.add(thighStripe)
      this.legs.push({ pivot, side })
    }

    this.group.position.set(0, 0, 6.4)
    this.group.rotation.y = Math.PI
    this.physics = {
      pos: new THREE.Vector3(0, 0, 6.4),
      radius: 0.38,
      walkSpeed: 3.35,
      sprintSpeed: 5.7,
      yaw: Math.PI,
      moveAmount: 0,
      speed: 0,
      stride: 0,
      time: 0,
    }
    this.health = 100
    this.maxHealth = 100
    this.energy = 100
    this.battery = 100
    this.flashlightOn = false
    this.hidden = false
    this.hideType = null
    this.sprinting = false
    this.lastDamage = -10
    this.alive = true
    this.onFootstep = null
    this.onDamage = null

    /* flashlight ------------------------------------------------------------ */
    this.flashlight = new THREE.SpotLight(0xbdf4ff, 0, 22, 0.5, 0.55, 1.4)
    this.flashlight.position.set(0, 1.6, 0.15)
    this.flashlight.target.position.set(0, -0.5, 5)
    this.group.add(this.flashlight)
    this.group.add(this.flashlight.target)
  }

  get position() { return this.physics.pos }

  setFlashlight(on) {
    if (on && this.battery <= 0) return false
    this.flashlightOn = on
    this.flashlight.intensity = on ? 55 : 0
    return true
  }

  setHidden(hidden, hideType = null) {
    this.hidden = hidden
    this.hideType = hideType
    if (hidden) {
      this.physics.speed = 0
      this.physics.moveAmount = 0
      if (hideType === 'locker') this.model.visible = false
      else {
        this.model.visible = true
        this.model.scale.set(1, 0.8, 1)
        this.model.position.y = -0.18
      }
      this.sprinting = false
    } else {
      this.model.visible = true
      this.model.scale.set(1, 1, 1)
      this.model.position.y = 0
    }
  }

  teleport(x, z, yaw = this.physics.yaw) {
    this.physics.pos.set(x, 0, z)
    this.physics.yaw = yaw
    this.group.position.set(x, 0, z)
    this.group.rotation.y = yaw
  }

  takeDamage(amount) {
    if (!this.alive) return false
    this.health = Math.max(0, this.health - amount)
    if (this.health <= 0) {
      this.alive = false
      return true
    }
    if (this.onDamage) this.onDamage(amount)
    return false
  }

  heal(amount) {
    this.health = Math.min(this.maxHealth, this.health + amount)
  }

  rechargeBattery(amount) {
    this.battery = Math.min(100, this.battery + amount)
  }

  update(dt, input, cameraYaw, world, canMove = true) {
    const p = this.physics
    p.time += dt
    if (!this.alive) {
      this.animate(dt, 0, false)
      return
    }

    let dx = 0, dz = 0
    const hasInput = canMove && !this.hidden && (input.x !== 0 || input.z !== 0)
    if (hasInput) {
      const len = Math.hypot(input.x, input.z)
      const ix = input.x / len, iz = input.z / len
      // camera-relative axes
      const fx = -Math.sin(cameraYaw), fz = -Math.cos(cameraYaw)
      const rx = Math.cos(cameraYaw), rz = -Math.sin(cameraYaw)
      dx = fx * iz + rx * ix
      dz = fz * iz + rz * ix
    }

    const wantSprint = canMove && !this.hidden && input.sprint && this.energy > 1 && hasInput
    this.sprinting = wantSprint
    if (wantSprint) this.energy = Math.max(0, this.energy - dt * 19)
    else this.energy = Math.min(100, this.energy + dt * (hasInput ? 8 : 13))

    const targetSpeed = hasInput ? (wantSprint ? p.sprintSpeed : p.walkSpeed) : 0
    const accel = hasInput ? 12 : 16
    p.speed += (targetSpeed - p.speed) * Math.min(1, dt * accel)
    if (p.speed < 0.02) p.speed = 0

    if (p.speed > 0.02 && hasInput) {
      const step = p.speed * dt
      resolveMovement(world.colliders, p.pos, dx * step, dz * step, p.radius)
      const targetYaw = Math.atan2(dx, dz)
      let diff = targetYaw - p.yaw
      while (diff > Math.PI) diff -= Math.PI * 2
      while (diff < -Math.PI) diff += Math.PI * 2
      p.yaw += diff * Math.min(1, dt * 12)
      p.moveAmount = Math.min(1, p.moveAmount + dt * 5)
      p.stride += step * (wantSprint ? 1.5 : 1.0)
      if (p.stride > (wantSprint ? 2.1 : 1.55)) {
        p.stride = 0
        if (this.onFootstep) this.onFootstep(wantSprint)
      }
    } else {
      p.moveAmount = Math.max(0, p.moveAmount - dt * 6)
      p.stride = Math.max(0, p.stride - dt)
    }

    // clamp to facility hard bounds just in case
    p.pos.x = Math.max(-30, Math.min(36, p.pos.x))
    p.pos.z = Math.max(-35, Math.min(31, p.pos.z))

    this.group.position.set(p.pos.x, 0, p.pos.z)
    this.group.rotation.y = p.yaw

    // flashlight battery
    if (this.flashlightOn) {
      this.battery = Math.max(0, this.battery - dt * 4.6)
      this.flashlight.intensity = 55 + Math.sin(p.time * 23) * 1.2
      if (this.battery <= 0) this.setFlashlight(false)
    } else {
      this.flashlight.intensity = 0
    }

    const moving = p.speed > 0.15 && hasInput
    this.animate(dt, p.moveAmount * (wantSprint ? 1.5 : 1), moving)
    this.visorGlow.material.opacity = 0.24 + Math.sin(p.time * 2.2) * 0.06
  }

  animate(dt, amount, moving) {
    const t = this.physics.time
    const walk = Math.sin(this.physics.stride * Math.PI * 2)
    const speedFactor = amount
    const idleBob = Math.sin(t * 1.7) * 0.012
    this.model.position.y = idleBob + (moving ? Math.abs(Math.sin(this.physics.stride * Math.PI * 2)) * 0.035 * speedFactor : 0)
    this.model.rotation.x = moving ? -0.05 * speedFactor : 0
    this.model.rotation.z = moving ? Math.sin(this.physics.stride * Math.PI) * 0.02 : 0

    this.head.rotation.y = Math.sin(t * 0.55) * 0.05
    this.head.rotation.x = Math.sin(t * 0.9) * 0.02

    for (const arm of this.arms) {
      const swing = walk * 0.72 * speedFactor * arm.side
      arm.pivot.rotation.x = swing + (moving ? 0 : Math.sin(t * 1.7 + arm.side) * 0.02)
      arm.pivot.rotation.z = arm.side * (0.06 + 0.03 * speedFactor)
    }
    for (const leg of this.legs) {
      const swing = walk * 0.68 * speedFactor * leg.side
      leg.pivot.rotation.x = swing
    }
    if (!moving) {
      for (const arm of this.arms) arm.pivot.rotation.x *= 0.9
      for (const leg of this.legs) leg.pivot.rotation.x *= 0.9
    }
    // subtle backpack float
    if (this.hidden && this.hideType === 'crates') {
      this.model.rotation.x = -0.22
      this.model.position.y = -0.18
    }
  }
}

/* ========================================================================== */
/* Third-person orbit camera with wall avoidance                              */
/* ========================================================================== */
export class ThirdPersonCamera {
  constructor(camera) {
    this.camera = camera
    this.yaw = Math.PI
    this.pitch = 0.24
    this.distance = 4.4
    this.zoom = 4.4
    this.target = new THREE.Vector3()
    this.smoothPos = new THREE.Vector3()
    this.smoothTarget = new THREE.Vector3()
    this.initialized = false
    this.shake = 0
    this.sensitivity = 0.0032
  }

  handleMouse(dx, dy) {
    this.yaw -= dx * this.sensitivity
    this.pitch += dy * this.sensitivity
    this.pitch = Math.max(-0.12, Math.min(1.0, this.pitch))
  }

  zoomBy(delta) {
    this.zoom = Math.max(2.6, Math.min(6.6, this.zoom + delta * 0.003))
  }

  addShake(amount) { this.shake = Math.min(0.25, this.shake + amount) }

  update(dt, player, world, hidden = false, hideType = null) {
    const py = player.position
    const targetY = hidden && hideType === 'crates' ? 0.85 : 1.36
    this.target.set(py.x, targetY, py.z)

    const desiredDist = hidden && hideType === 'locker' ? 2.4 : this.zoom
    const horiz = Math.cos(this.pitch) * desiredDist
    const vert = Math.sin(this.pitch) * desiredDist
    let camX = py.x + Math.sin(this.yaw) * horiz
    let camZ = py.z + Math.cos(this.yaw) * horiz
    let camY = targetY + vert

    // camera collision: step along the horizontal ray to the wall
    if (!hidden) {
      const steps = 12
      let safe = 1
      for (let i = 1; i <= steps; i++) {
        const t = i / steps
        const x = py.x + (camX - py.x) * t
        const z = py.z + (camZ - py.z) * t
        let blocked = false
        for (let j = 0; j < world.colliders.length; j++) {
          const c = world.colliders[j]
          if (!c.solid) continue
          if (x > c.minX - 0.22 && x < c.maxX + 0.22 && z > c.minZ - 0.22 && z < c.maxZ + 0.22) {
            blocked = true
            break
          }
        }
        if (blocked) { safe = Math.max(0.18, (i - 1) / steps); break }
      }
      if (safe < 1) {
        const shrink = Math.max(0.4, safe * desiredDist - 0.35)
        const f = shrink / desiredDist
        camX = py.x + (camX - py.x) * f
        camZ = py.z + (camZ - py.z) * f
        camY = targetY + vert * Math.max(0.4, f)
      }
    }
    camY = Math.max(0.55, Math.min(3.85, camY))

    if (!this.initialized) {
      this.smoothPos.set(camX, camY, camZ)
      this.smoothTarget.copy(this.target)
      this.initialized = true
    } else {
      const k = 1 - Math.exp(-dt * 11)
      this.smoothPos.x += (camX - this.smoothPos.x) * k
      this.smoothPos.y += (camY - this.smoothPos.y) * k
      this.smoothPos.z += (camZ - this.smoothPos.z) * k
      this.smoothTarget.lerp(this.target, 1 - Math.exp(-dt * 16))
    }

    this.shake *= Math.exp(-dt * 9)
    const shakeX = (Math.random() - 0.5) * this.shake
    const shakeY = (Math.random() - 0.5) * this.shake
    this.camera.position.set(this.smoothPos.x + shakeX, this.smoothPos.y + shakeY, this.smoothPos.z)
    this.camera.lookAt(this.smoothTarget.x, this.smoothTarget.y + 0.1, this.smoothTarget.z)
    this.camera.rotation.z = 0
  }
}

import * as THREE from 'three'
import { canvasTexture, glowTexture, makeSprite } from './world/materials.js'
import { resolveMovement, segmentBlocked } from './world/outpost.js'

/* -------------------------------------------------------------------------- */
/* State indicators                                                           */
/* -------------------------------------------------------------------------- */
function indicatorTexture(symbol, color) {
  return canvasTexture(64, 64, (ctx, w, h) => {
    ctx.clearRect(0, 0, w, h)
    ctx.beginPath()
    ctx.arc(w / 2, h / 2, 25, 0, Math.PI * 2)
    ctx.fillStyle = 'rgba(3,10,14,.78)'
    ctx.fill()
    ctx.strokeStyle = color
    ctx.lineWidth = 2
    ctx.stroke()
    ctx.fillStyle = color
    ctx.font = 'bold 34px monospace'
    ctx.textAlign = 'center'
    ctx.textBaseline = 'middle'
    ctx.fillText(symbol, w / 2, h / 2 + 2)
  })
}

const INDICATORS = {
  patrol: indicatorTexture('·', '#6ce8ff'),
  suspicious: indicatorTexture('?', '#ffa14d'),
  investigate: indicatorTexture('?', '#ffa14d'),
  search: indicatorTexture('?', '#ffa14d'),
  chase: indicatorTexture('!', '#ff4a42'),
}

/* ========================================================================== */
/* Hovering security sentinel                                                 */
/* ========================================================================== */
export class SecurityRobot {
  constructor(scene, options) {
    this.scene = scene
    this.name = options.name || 'K-7'
    this.patrol = options.patrol
    this.patrolIndex = 0
    this.state = 'patrol'
    this.detection = 0
    this.visible = false
    this.lastSeen = new THREE.Vector3(options.start.x, 0, options.start.z)
    this.target = new THREE.Vector3(options.start.x, 0, options.start.z)
    this.losTimer = 0
    this.stateTimer = 0
    this.waitTimer = 0
    this.attackTimer = 0
    this.scanPhase = Math.random() * 6.28
    this.time = Math.random() * 10
    this.dead = false
    this.onStateChange = null
    this.onDetect = null
    this.onAttack = null
    this.visionRange = options.visionRange || 13
    this.visionHalfCos = Math.cos((options.fov || 72) * Math.PI / 360)
    this.speed = 0
    this.yaw = Math.random() * Math.PI * 2
    this.physics = { pos: new THREE.Vector3(options.start.x, 0, options.start.z), radius: 0.48 }
    this.build(options.start)
    this.enterPatrol(true)
  }

  get position() { return this.physics.pos }

  build(start) {
    const armor = new THREE.MeshStandardMaterial({ color: 0x2b2c30, roughness: 0.48, metalness: 0.7 })
    const armorDark = new THREE.MeshStandardMaterial({ color: 0x15171a, roughness: 0.58, metalness: 0.62 })
    const trim = new THREE.MeshStandardMaterial({ color: 0x4b3a2a, roughness: 0.4, metalness: 0.7 })
    const eyeOff = new THREE.MeshBasicMaterial({ color: 0xff9a3d })
    const eyeAlert = new THREE.MeshBasicMaterial({ color: 0xff3a30 })
    this.eyeMat = eyeOff
    this.eyeAlertMat = eyeAlert

    const root = new THREE.Group()
    root.position.set(start.x, 0, start.z)
    this.scene.add(root)
    this.group = root
    this.body = new THREE.Group()
    root.add(this.body)

    // hover ring + underglow
    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.42, 0.055, 5, 18), trim)
    ring.rotation.x = Math.PI / 2
    ring.position.y = 0.36
    this.body.add(ring)
    const innerRing = new THREE.Mesh(new THREE.TorusGeometry(0.28, 0.02, 4, 16), eyeOff)
    innerRing.rotation.x = Math.PI / 2
    innerRing.position.y = 0.33
    this.body.add(innerRing)
    const ringGlow = makeSprite(glowTexture(), 0xff8a3a, 1.6, 0.22)
    ringGlow.position.y = 0.33
    this.body.add(ringGlow)
    this.ringGlow = ringGlow
    this.ring = innerRing

    const glowPlane = new THREE.Mesh(
      new THREE.PlaneGeometry(1.6, 1.6),
      new THREE.MeshBasicMaterial({ map: glowTexture(), color: 0xff8a3a, transparent: true, opacity: 0.18, depthWrite: false, blending: THREE.AdditiveBlending }),
    )
    glowPlane.rotation.x = -Math.PI / 2
    glowPlane.position.y = 0.04
    root.add(glowPlane)
    this.groundGlow = glowPlane

    // lower chassis
    const lower = new THREE.Mesh(new THREE.CylinderGeometry(0.34, 0.46, 0.45, 8), armorDark)
    lower.position.y = 0.62
    this.body.add(lower)
    const collar = new THREE.Mesh(new THREE.CylinderGeometry(0.42, 0.36, 0.1, 8), trim)
    collar.position.y = 0.88
    this.body.add(collar)

    // torso
    const torso = new THREE.Mesh(new THREE.BoxGeometry(0.64, 0.72, 0.44), armor)
    torso.position.y = 1.23
    this.body.add(torso)
    const chestPlate = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.44, 0.08), armorDark)
    chestPlate.position.set(0, 1.3, 0.24)
    this.body.add(chestPlate)
    const core = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.09, 0.06, 10), eyeOff)
    core.rotation.x = Math.PI / 2
    core.position.set(0, 1.3, 0.29)
    this.body.add(core)
    this.core = core
    const coreGlow = makeSprite(glowTexture(), 0xff7a2a, 0.7, 0.3)
    coreGlow.position.set(0, 1.3, 0.34)
    this.body.add(coreGlow)
    this.coreGlow = coreGlow
    for (let i = 0; i < 3; i++) {
      const vent = new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.03, 0.03), trim)
      vent.position.set(0, 1.02 + i * 0.08, 0.24)
      this.body.add(vent)
    }

    // shoulders / manipulators
    for (const side of [-1, 1]) {
      const pod = new THREE.Mesh(new THREE.BoxGeometry(0.18, 0.28, 0.3), armor)
      pod.position.set(side * 0.42, 1.45, 0)
      this.body.add(pod)
      const light = new THREE.Mesh(new THREE.BoxGeometry(0.025, 0.16, 0.02), eyeOff)
      light.position.set(side * 0.52, 1.45, 0.02)
      this.body.add(light)
      const arm = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.035, 0.62, 6), armorDark)
      arm.position.set(side * 0.44, 1.02, 0.05)
      arm.rotation.z = side * 0.16
      this.body.add(arm)
      const stun = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.03, 0.32, 6), trim)
      stun.position.set(side * 0.52, 0.66, 0.07)
      this.body.add(stun)
      const stunTip = new THREE.Mesh(new THREE.SphereGeometry(0.05, 6, 5), eyeOff)
      stunTip.position.set(side * 0.53, 0.51, 0.07)
      this.body.add(stunTip)
    }

    // head / optic
    this.head = new THREE.Group()
    this.head.position.set(0, 1.68, 0)
    this.body.add(this.head)
    const skull = new THREE.Mesh(new THREE.BoxGeometry(0.44, 0.25, 0.4), armor)
    this.head.add(skull)
    const brow = new THREE.Mesh(new THREE.BoxGeometry(0.48, 0.06, 0.44), armorDark)
    brow.position.y = 0.1
    this.head.add(brow)
    const visorRecess = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.1, 0.05), armorDark)
    visorRecess.position.set(0, 0.0, 0.21)
    this.head.add(visorRecess)
    this.eye = new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.045, 0.03), eyeOff)
    this.eye.position.set(0, 0.0, 0.24)
    this.head.add(this.eye)
    this.eyeGlow = makeSprite(glowTexture(), 0xff7a2a, 0.9, 0.4)
    this.eyeGlow.position.set(0, 0.0, 0.3)
    this.head.add(this.eyeGlow)
    // antenna
    const ant = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.02, 0.34, 5), armorDark)
    ant.position.set(0.14, 0.27, -0.08)
    ant.rotation.z = -0.25
    this.head.add(ant)
    const antTip = new THREE.Mesh(new THREE.SphereGeometry(0.03, 5, 4), eyeOff)
    antTip.position.set(0.18, 0.43, -0.08)
    this.head.add(antTip)

    // state indicator
    const stateMat = new THREE.SpriteMaterial({ map: INDICATORS.patrol, transparent: true, depthWrite: false, depthTest: false })
    this.stateSprite = new THREE.Sprite(stateMat)
    this.stateSprite.scale.set(0.45, 0.45, 1)
    this.stateSprite.position.y = 2.35
    root.add(this.stateSprite)

    // subtle search light cone on the floor (fake, no realtime light)
    const coneMat = new THREE.MeshBasicMaterial({ color: 0xffa14d, transparent: true, opacity: 0.05, depthWrite: false, side: THREE.DoubleSide, blending: THREE.AdditiveBlending })
    const cone = new THREE.Mesh(new THREE.CircleGeometry(2.8, 18, -0.45, 0.9), coneMat)
    cone.rotation.x = -Math.PI / 2
    cone.position.set(0, 0.06, 1.4)
    root.add(cone)
    this.scanCone = cone
    this.scanConeMat = coneMat

    // shadows
    this.body.traverse((o) => {
      if (o.isMesh && !o.material.transparent) o.castShadow = true
    })
  }

  setState(next) {
    if (this.state === next) return
    this.state = next
    this.stateTimer = 0
    const tex = INDICATORS[next] || INDICATORS.patrol
    this.stateSprite.material.map = tex
    this.stateSprite.material.needsUpdate = true
    const alert = next === 'chase'
    this.eyeMat.color.set(alert ? 0xff3a30 : next === 'patrol' ? 0xff9a3d : 0xffb45c)
    const color = alert ? 0xff3a30 : 0xffa14d
    this.eyeGlow.material.color.set(color)
    this.ringGlow.material.color.set(color)
    this.ring.material.color.set(alert ? 0xff3a30 : 0xff9a3d)
    this.groundGlow.material.color.set(color)
    this.core.material.color.set(alert ? 0xff3a30 : 0xff9a3d)
    this.coreGlow.material.color.set(color)
    this.scanConeMat.color.set(alert ? 0xff3a30 : 0xffa14d)
    this.scanConeMat.opacity = alert ? 0.12 : 0.055
    if (this.onStateChange) this.onStateChange(this, next)
    if (next === 'chase' && this.onDetect) this.onDetect(this)
  }

  enterPatrol(initial = false) {
    this.setState('patrol')
    if (initial) {
      let best = 0, bestD = Infinity
      for (let i = 0; i < this.patrol.length; i++) {
        const d = this.patrol[i].x * this.patrol[i].x + this.patrol[i].z * this.patrol[i].z
        const dx = this.position.x - this.patrol[i].x
        const dz = this.position.z - this.patrol[i].z
        const dd = dx * dx + dz * dz
        if (dd < bestD) { bestD = dd; best = i }
      }
      this.patrolIndex = best
    }
    this.target.set(this.patrol[this.patrolIndex].x, 0, this.patrol[this.patrolIndex].z)
  }

  alertTo(pos, immediate = false) {
    if (this.state === 'chase' || this.dead) return
    this.lastSeen.set(pos.x, 0, pos.z)
    this.target.set(pos.x, 0, pos.z)
    this.setState('investigate')
    this.stateTimer = 0
    this.detection = Math.max(this.detection, 0.35)
    if (immediate) this.detection = Math.min(0.9, this.detection + 0.3)
  }

  canSee(player, world) {
    if (player.hidden || !player.alive) return false
    const px = player.position.x
    const pz = player.position.z
    const dx = px - this.position.x
    const dz = pz - this.position.z
    const dist = Math.hypot(dx, dz)
    if (dist > this.visionRange) return false
    const fx = Math.sin(this.yaw)
    const fz = Math.cos(this.yaw)
    const dot = (dx * fx + dz * fz) / (dist || 1)
    const inCone = dot >= this.visionHalfCos
    const close = dist < 3.0
    if (!inCone && !close) return false
    if (segmentBlocked(world.colliders, this.position.x, this.position.z, px, pz)) return false
    return true
  }

  moveToward(tx, tz, speed, dt, world) {
    const dx = tx - this.position.x
    const dz = tz - this.position.z
    const dist = Math.hypot(dx, dz)
    if (dist < 0.1) { this.speed *= 0.8; return dist }
    const nx = dx / dist, nz = dz / dist
    const step = Math.min(speed * dt, dist)
    resolveMovement(world.colliders, this.physics.pos, nx * step, nz * step, this.physics.radius)
    const targetYaw = Math.atan2(nx, nz)
    let diff = targetYaw - this.yaw
    while (diff > Math.PI) diff -= Math.PI * 2
    while (diff < -Math.PI) diff += Math.PI * 2
    this.yaw += diff * Math.min(1, dt * 7)
    this.speed = speed
    return dist
  }

  update(dt, player, world, allowUpdate = true) {
    this.time += dt
    if (this.dead) return
    const canSee = allowUpdate && player.alive && this.canSee(player, world)
    this.visible = canSee
    if (canSee) {
      this.lastSeen.set(player.position.x, 0, player.position.z)
      this.losTimer = 0
    } else {
      this.losTimer += dt
    }

    const distToPlayer = Math.hypot(player.position.x - this.position.x, player.position.z - this.position.z)
    const movingPlayer = player.physics.speed > 4.5
    const detectionRate = (0.55 + Math.max(0, 1 - distToPlayer / this.visionRange) * 1.15) * (movingPlayer ? 1.35 : 1)

    if (allowUpdate) {
      switch (this.state) {
        case 'patrol': {
          if (canSee) {
            this.detection = Math.min(1, this.detection + detectionRate * dt)
            if (this.detection >= 1) this.startChase()
            else if (this.detection > 0.3) {
              this.setState('suspicious')
              this.stateTimer = 0
            } else {
              this.patrolStep(dt, world)
            }
          } else {
            this.detection = Math.max(0, this.detection - dt * 0.4)
            this.patrolStep(dt, world)
          }
          break
        }
        case 'suspicious': {
          this.speed *= 0.85
          if (canSee) {
            this.detection = Math.min(1, this.detection + detectionRate * 1.1 * dt)
            this.faceToward(player.position.x, player.position.z, dt, 8)
            if (this.detection >= 1) this.startChase()
          } else {
            this.detection = Math.max(0, this.detection - dt * 0.35)
            this.stateTimer += dt
            if (this.stateTimer > 1.4) {
              this.target.copy(this.lastSeen)
              this.setState('search')
              this.stateTimer = 0
            }
          }
          break
        }
        case 'chase': {
          const targetDist = Math.hypot(this.lastSeen.x - this.position.x, this.lastSeen.z - this.position.z)
          if (canSee) {
            this.detection = 1
            this.lastSeen.set(player.position.x, 0, player.position.z)
            this.target.copy(this.lastSeen)
          } else {
            this.detection = Math.max(0.35, this.detection - dt * 0.08)
            if (this.losTimer > 1.3) this.target.copy(this.lastSeen)
            if (this.losTimer > 5.5) {
              this.setState('search')
              this.stateTimer = 0
            }
          }
          const d = this.moveToward(this.target.x, this.target.z, 3.55, dt, world)
          if (canSee && distToPlayer < 1.55) {
            this.speed *= 0.4
            this.faceToward(player.position.x, player.position.z, dt, 10)
            this.attackTimer -= dt
            if (this.attackTimer <= 0) {
              this.attackTimer = 0.95
              if (this.onAttack) this.onAttack(this, 12)
            }
          } else {
            this.attackTimer = Math.min(this.attackTimer, 0.35)
          }
          if (d < 1.0 && !canSee) {
            this.setState('search')
            this.stateTimer = 0
          }
          // ally alert
          break
        }
        case 'search': {
          this.stateTimer += dt
          const d = this.moveToward(this.target.x, this.target.z, 1.85, dt, world)
          if (canSee) {
            this.detection = Math.min(1, this.detection + detectionRate * 1.3 * dt)
            if (this.detection >= 0.8) this.startChase()
          } else {
            this.detection = Math.max(0, this.detection - dt * 0.25)
          }
          if (d < 0.8) {
            // scan around
            this.yaw += dt * 0.9 * Math.sin(this.time * 1.7 + this.scanPhase)
            this.speed *= 0.8
          }
          if (this.stateTimer > 5.5) this.returnToPatrol()
          break
        }
        case 'investigate': {
          this.stateTimer += dt
          const d = this.moveToward(this.target.x, this.target.z, 2.15, dt, world)
          if (canSee) {
            this.detection = Math.min(1, this.detection + detectionRate * 1.3 * dt)
            if (this.detection >= 0.85) this.startChase()
          }
          if (d < 0.9) {
            this.speed *= 0.7
            this.yaw += dt * 0.6 * Math.sin(this.time * 1.4 + this.scanPhase)
          }
          if (this.stateTimer > 7.0) this.returnToPatrol()
          break
        }
        case 'return': {
          const wp = this.patrol[this.returnIndex === undefined ? this.patrolIndex : this.returnIndex]
          const d = this.moveToward(wp.x, wp.z, 1.6, dt, world)
          if (canSee) {
            this.detection = Math.min(1, this.detection + detectionRate * dt)
            if (this.detection >= 0.9) this.startChase()
          }
          if (d < 0.7) {
            this.setState('patrol')
            this.waitTimer = 1.0
          }
          break
        }
      }
    }

    // state indicator / eye animation
    const alert = this.state === 'chase'
    this.stateSprite.material.opacity = this.state === 'patrol' ? 0.3 : 0.85
    this.stateSprite.scale.setScalar(alert ? 0.52 + Math.sin(this.time * 8) * 0.04 : 0.42)
    this.stateSprite.position.y = 2.35 + Math.sin(this.time * 2) * 0.04
    const eyePulse = alert ? 0.7 + Math.sin(this.time * 14) * 0.3 : 0.55 + Math.sin(this.time * 3) * 0.15
    this.eyeGlow.material.opacity = eyePulse
    this.coreGlow.material.opacity = eyePulse * 0.7
    this.ringGlow.material.opacity = 0.16 + Math.sin(this.time * 5) * 0.04

    // visual movement animation
    const moveSpeed = Math.max(0, this.speed)
    const hover = 0.06 + Math.sin(this.time * 2.6) * 0.018
    this.body.position.y = hover + (alert ? 0.04 : 0)
    this.body.rotation.x = THREE.MathUtils.damp(this.body.rotation.x, alert ? -0.12 : 0, 4, dt)
    this.body.rotation.z = Math.sin(this.time * 1.3) * 0.015
    this.ring.rotation.z += dt * (alert ? 3.5 : 1.3)
    this.scanCone.position.y = 0.07
    this.groundGlow.material.opacity = alert ? 0.28 : 0.14 + Math.sin(this.time * 2.4) * 0.03
    // head tracks forward + small scan
    const headTargetYaw = this.yaw
    let diff = headTargetYaw - this.head.rotation.y
    while (diff > Math.PI) diff -= Math.PI * 2
    while (diff < -Math.PI) diff += Math.PI * 2
    this.head.rotation.y += diff * Math.min(1, dt * 5)
    if (!alert && moveSpeed < 0.2) {
      this.head.rotation.y = Math.sin(this.time * 0.8 + this.scanPhase) * 0.6
    }

    this.group.position.set(this.position.x, 0, this.position.z)
    this.group.rotation.y = this.yaw
    this.eye.material = alert ? this.eyeAlertMat : this.eyeMat

    // decelerate visual speed
    if (!allowUpdate) this.speed *= 0.9
  }

  faceToward(x, z, dt, rate = 6) {
    const targetYaw = Math.atan2(x - this.position.x, z - this.position.z)
    let diff = targetYaw - this.yaw
    while (diff > Math.PI) diff -= Math.PI * 2
    while (diff < -Math.PI) diff += Math.PI * 2
    this.yaw += diff * Math.min(1, dt * rate)
  }

  patrolStep(dt, world) {
    if (this.waitTimer > 0) {
      this.waitTimer -= dt
      this.speed *= 0.85
      // scan at waypoint
      this.yaw += dt * 0.6 * Math.sin(this.time * 1.4 + this.scanPhase)
      if (this.waitTimer <= 0) {
        this.patrolIndex = (this.patrolIndex + 1) % this.patrol.length
        this.target.set(this.patrol[this.patrolIndex].x, 0, this.patrol[this.patrolIndex].z)
      }
      return
    }
    const d = this.moveToward(this.target.x, this.target.z, 1.35, dt, world)
    if (d < 0.55) {
      this.waitTimer = 1.1 + Math.random() * 1.4
      this.detection = Math.max(0, this.detection - 0.15)
    }
  }

  returnToPatrol() {
    this.setState('return')
    this.detection *= 0.4
    this.returnIndex = this.patrolIndex
    this.target.set(this.patrol[this.returnIndex].x, 0, this.patrol[this.returnIndex].z)
    this.waitTimer = 0
  }

  startChase() {
    if (this.state === 'chase') return
    this.detection = 1
    this.setState('chase')
    this.attackTimer = 0.5
    this.target.copy(this.lastSeen)
  }

  get isAlerted() {
    return this.state === 'chase' || this.state === 'search' || this.state === 'investigate' || this.state === 'suspicious'
  }
}

