import { RARITY_CLASS } from './loot.js'

const ICONS = {
  document: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4"><path d="M5 2.5h9l5 5v14H5z"/><path d="M14 2.5v5h5M8 12h8M8 15.5h8M8 8.5h3"/><circle cx="16.5" cy="18" r="2.2"/></svg>',
  component: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3"><rect x="6" y="6" width="12" height="12" rx="1"/><rect x="9.5" y="9.5" width="5" height="5"/><path d="M9 2v4M15 2v4M9 18v4M15 18v4M2 9h4M2 15h4M18 9h4M18 15h4"/></svg>',
  cell: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4"><rect x="7" y="4" width="10" height="17" rx="2"/><path d="M10 2h4M9.5 8h5M9.5 17h5"/><path d="M12 10l-1.5 3h3L12 16" stroke-width="1.2"/></svg>',
  module: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3"><path d="M12 2l7 5v10l-7 5-7-5V7z"/><path d="M12 7l3.5 2.5v5L12 17l-3.5-2.5v-5z"/><circle cx="12" cy="12" r="1.2" fill="currentColor"/></svg>',
}

function icon(shape, color) {
  const c = '#' + color.toString(16).padStart(6, '0')
  return `<span style="color:${c};display:block;width:100%;height:100%">${ICONS[shape] || ICONS.component}</span>`
}

function fmtTime(seconds) {
  const s = Math.max(0, Math.floor(seconds))
  const m = Math.floor(s / 60)
  return `${String(m).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`
}

function fmtClock(seconds) {
  const s = Math.max(0, Math.floor(seconds))
  const h = Math.floor(s / 3600)
  return `${String(h).padStart(2, '0')}:${String(Math.floor((s % 3600) / 60)).padStart(2, '0')}:${String(s % 60).padStart(2, '0')}`
}

export class UI {
  constructor() {
    this.callbacks = {}
    this.mobile = false
    this.toastCount = 0
    this.lastInventorySig = ''
    this.lastBattery = -1
    this.screens = ['title', 'pause', 'inventory', 'log', 'dead', 'complete']
    this.el = {}
    const ids = [
      'hud', 'objective-text', 'objective-sub', 'objective-dist', 'objective-fill',
      'health-num', 'health-bar', 'energy-num', 'energy-bar', 'battery-num', 'battery-bar',
      'threat-dot', 'threat-text', 'signal-state', 'quick-slots', 'inv-count',
      'prompt-key', 'prompt-text', 'interact-prompt', 'extract-panel', 'extract-fill', 'extract-time',
      'hidden-indicator', 'toast-stack', 'damage-vignette', 'objective-marker', 'marker-label', 'marker-dist',
      'screen-title', 'screen-pause', 'screen-inventory', 'screen-log', 'screen-dead', 'screen-complete',
      'inventory-grid', 'inv-research', 'inv-credits', 'inv-slots', 'clearance-line',
      'log-source', 'log-title', 'log-body', 'complete-time', 'complete-research', 'complete-credits', 'complete-list',
      'loading', 'load-fill', 'load-status', 'btn-start', 'btn-title-audio', 'btn-title-quality',
      'btn-resume', 'btn-pause-audio', 'btn-restart', 'btn-close-inventory', 'btn-close-log', 'btn-retry', 'btn-replay',
      'btn-flashlight', 'btn-inventory', 'btn-pause', 'joystick', 'joystick-stick', 'look-hint',
      'btn-touch-sprint', 'btn-touch-interact', 'btn-touch-flashlight', 'btn-touch-inventory',
      'title-clock', 'error-panel', 'error-text',
    ]
    for (const id of ids) this.el[id] = document.getElementById(id)
    this.qualityButtons = [...document.querySelectorAll('[data-quality]')]
    this.mobile = window.matchMedia('(pointer: coarse)').matches || navigator.maxTouchPoints > 0
    if (this.mobile) document.body.classList.add('is-mobile')
    this.el.hud.classList.add('hud-off')
    this.buildQuickSlots()
    this.bind()
  }

  on(name, fn) { this.callbacks[name] = fn }

  emit(name, ...args) {
    const fn = this.callbacks[name]
    if (fn) fn(...args)
  }

  bind() {
    const click = (el, name) => {
      if (!el) return
      el.addEventListener('click', (e) => {
        e.preventDefault()
        this.emit('uiSound')
        this.emit(name)
      })
    }
    click(this.el['btn-start'], 'start')
    click(this.el['btn-title-audio'], 'audio')
    click(this.el['btn-title-quality'], 'qualityCycle')
    click(this.el['btn-resume'], 'resume')
    click(this.el['btn-pause-audio'], 'audio')
    click(this.el['btn-restart'], 'restart')
    click(this.el['btn-close-inventory'], 'closeInventory')
    click(this.el['btn-close-log'], 'closeLog')
    click(this.el['btn-retry'], 'restart')
    click(this.el['btn-replay'], 'restart')
    click(this.el['btn-flashlight'], 'flashlight')
    click(this.el['btn-inventory'], 'inventory')
    click(this.el['btn-pause'], 'pause')
    click(this.el['btn-touch-inventory'], 'inventory')
    click(this.el['btn-touch-flashlight'], 'flashlight')
    click(this.el['btn-touch-interact'], 'interact')
    click(this.el['btn-touch-interact'], 'uiSound')

    for (const b of this.qualityButtons) {
      b.addEventListener('click', (e) => {
        e.preventDefault()
        this.emit('quality', b.dataset.quality)
      })
    }

    // hold-sprint on mobile
    const sprint = this.el['btn-touch-sprint']
    const setSprint = (on) => {
      sprint.classList.toggle('active', on)
      this.emit('sprintHold', on)
    }
    sprint.addEventListener('pointerdown', (e) => { e.preventDefault(); sprint.setPointerCapture(e.pointerId); setSprint(true) })
    sprint.addEventListener('pointerup', (e) => { e.preventDefault(); setSprint(false) })
    sprint.addEventListener('pointercancel', () => setSprint(false))
    sprint.addEventListener('pointerleave', () => setSprint(false))

    // inventory drop delegation
    this.el['inventory-grid'].addEventListener('click', (e) => {
      const btn = e.target.closest('[data-drop]')
      if (!btn) return
      e.preventDefault()
      this.emit('uiSound')
      this.emit('drop', btn.dataset.drop)
    })

    // quick slot click opens pack
    this.el['quick-slots'].addEventListener('click', () => this.emit('inventory'))
  }

  buildQuickSlots() {
    const wrap = this.el['quick-slots']
    wrap.innerHTML = ''
    for (let i = 0; i < 6; i++) {
      const slot = document.createElement('div')
      slot.className = 'quick-slot empty'
      slot.dataset.slot = String(i)
      wrap.appendChild(slot)
    }
  }

  setMobileButtonsVisible(visible) {
    if (visible) document.body.classList.add('is-mobile')
    else document.body.classList.remove('is-mobile')
  }

  showScreen(name) {
    for (const s of this.screens) {
      const el = this.el[`screen-${s}`]
      if (!el) continue
      el.classList.toggle('hidden', s !== name)
    }
    if (name) this.el.hud.classList.add('hud-off')
  }

  hideScreens() {
    for (const s of this.screens) this.el[`screen-${s}`].classList.add('hidden')
    this.el.hud.classList.remove('hud-off')
  }

  showTitle() {
    this.showScreen('title')
    this.el['screen-title'].classList.remove('hidden')
  }

  showPause() { this.showScreen('pause') }
  showInventory() { this.showScreen('inventory') }
  showLog() { this.showScreen('log') }
  showDead() { this.showScreen('dead') }
  showComplete() { this.showScreen('complete') }

  setLoading(progress, status) {
    this.el['load-fill'].style.width = `${Math.round(progress * 100)}%`
    if (status) this.el['load-status'].textContent = status
  }

  hideLoading() {
    this.el.loading.classList.add('done')
    setTimeout(() => this.el.loading.classList.add('hidden'), 550)
  }

  setError(text) {
    this.el.loading.classList.add('hidden')
    this.el['error-panel'].classList.remove('hidden')
    this.el['error-text'].textContent = text
  }

  setTitleClock(seconds) {
    this.el['title-clock'].textContent = `T+ ${fmtClock(seconds)}`
  }

  /* ------------------------------ HUD ----------------------------------- */
  setVitals(health, energy, battery) {
    const h = Math.max(0, Math.min(100, health))
    const e = Math.max(0, Math.min(100, energy))
    const b = Math.max(0, Math.min(100, battery))
    this.el['health-num'].textContent = Math.round(h)
    this.el['energy-num'].textContent = Math.round(e)
    this.el['battery-num'].textContent = Math.round(b)
    this.el['health-bar'].style.transform = `scaleX(${h / 100})`
    this.el['energy-bar'].style.transform = `scaleX(${e / 100})`
    this.el['battery-bar'].style.transform = `scaleX(${b / 100})`
    this.el['btn-flashlight'].classList.toggle('active', this.flashlightOn)
    if (this.lastBattery >= 0 && b < this.lastBattery - 0.2) {
      this.el['battery-num'].style.color = '#ffa14d'
    } else if (b > 99) {
      this.el['battery-num'].style.color = ''
    }
    this.lastBattery = b
  }

  setFlashlight(on) {
    this.flashlightOn = on
    this.el['btn-flashlight'].classList.toggle('active', on)
  }

  setObjective(text, sub, dist, progress) {
    this.el['objective-text'].textContent = text
    this.el['objective-sub'].textContent = sub
    this.el['objective-dist'].textContent = dist === null ? '-- M' : `${Math.round(dist)} M`
    if (progress !== null) this.el['objective-fill'].style.width = `${Math.max(0, Math.min(1, progress)) * 100}%`
  }

  setThreat(level, text) {
    const dot = this.el['threat-dot']
    dot.className = 'threat-dot' + (level >= 2 ? ' alert' : level >= 1 ? ' warn' : '')
    this.el['threat-text'].textContent = text
    const sig = this.el['signal-state']
    sig.textContent = level >= 2 ? 'HOSTILE' : level >= 1 ? 'CONTACT' : 'LINK OK'
    sig.className = level >= 2 ? 'signal-bad' : level >= 1 ? 'signal-warn' : 'signal-ok'
  }

  setPrompt(text, key = 'E', show = true) {
    if (show && text) {
      this.el['prompt-text'].textContent = text
      this.el['prompt-key'].textContent = key
      this.el['interact-prompt'].classList.add('show')
      this.el['btn-touch-interact'].classList.add('hot')
    } else {
      this.el['interact-prompt'].classList.remove('show')
      this.el['btn-touch-interact'].classList.remove('hot')
    }
  }

  setHidden(hidden) {
    this.el['hidden-indicator'].classList.toggle('show', hidden)
  }

  setMarker(show, x, y, dist, label = 'OBJECTIVE') {
    const m = this.el['objective-marker']
    m.classList.toggle('show', show)
    if (!show) return
    m.style.left = `${x}px`
    m.style.top = `${y}px`
    this.el['marker-dist'].textContent = dist === null ? '' : `${Math.round(dist)}M`
    this.el['marker-label'].textContent = label
  }

  setExtraction(active, progress = 0, seconds = 0) {
    this.el['extract-panel'].classList.toggle('active', active)
    if (!active) return
    this.el['extract-fill'].style.width = `${Math.max(0, Math.min(1, progress)) * 100}%`
    this.el['extract-time'].textContent = fmtTime(Math.ceil(seconds))
  }

  flashDamage() {
    const v = this.el['damage-vignette']
    v.classList.add('hit')
    clearTimeout(this.damageTimer)
    this.damageTimer = setTimeout(() => v.classList.remove('hit'), 140)
  }

  toast(title, sub = '', rarity = '', duration = 3000) {
    const stack = this.el['toast-stack']
    while (stack.children.length >= 4) stack.removeChild(stack.firstChild)
    const t = document.createElement('div')
    t.className = `toast ${rarity ? RARITY_CLASS[rarity] || `r-${rarity}` : ''}`
    t.innerHTML = `<b>${title}</b>${sub ? `<span class="t-sub">${sub}</span>` : ''}`
    stack.appendChild(t)
    setTimeout(() => {
      t.classList.add('out')
      setTimeout(() => t.remove(), 340)
    }, duration)
  }

  /* --------------------------- Inventory -------------------------------- */
  renderInventory(items, researchCount, credits, hasKeycard, open = false) {
    const sig = items.map((i) => i.uid).join(',') + `|${researchCount}|${credits}|${hasKeycard}|${open}`
    if (sig === this.lastInventorySig) return
    this.lastInventorySig = sig

    this.el['inv-count'].textContent = `${items.length}/6`
    this.el['inv-research'].textContent = String(researchCount)
    this.el['inv-credits'].textContent = String(credits)
    this.el['inv-slots'].textContent = `${items.length}/6`
    this.el['clearance-line'].innerHTML = `SECURITY CLEARANCE: <b>${hasKeycard ? 'LEVEL 4 — RESEARCH' : 'NONE'}</b>`

    // quick slots
    const slots = this.el['quick-slots'].children
    for (let i = 0; i < 6; i++) {
      const slot = slots[i]
      const item = items[i]
      slot.className = 'quick-slot'
      if (item) {
        const meta = item.meta
        slot.classList.add('filled', RARITY_CLASS[meta.rarity] || 'r-common')
        if (meta.research) slot.classList.add('research')
        slot.title = `${meta.name} — ${meta.rarityLabel}`
        slot.innerHTML = `<span class="slot-glyph">${icon(meta.shape, meta.color)}</span><i class="slot-rarity"></i>`
      } else {
        slot.classList.add('empty')
        slot.title = 'Empty slot'
        slot.innerHTML = ''
      }
    }

    // full inventory overlay
    const grid = this.el['inventory-grid']
    grid.innerHTML = ''
    for (let i = 0; i < 6; i++) {
      const item = items[i]
      if (!item) {
        const card = document.createElement('div')
        card.className = 'inv-card empty'
        card.innerHTML = `SLOT ${String(i + 1).padStart(2, '0')}<br />EMPTY`
        grid.appendChild(card)
        continue
      }
      const meta = item.meta
      const card = document.createElement('div')
      card.className = `inv-card ${RARITY_CLASS[meta.rarity] || 'r-common'}`
      card.innerHTML = `
        <div class="inv-top">
          <span class="inv-icon">${icon(meta.shape, meta.color)}</span>
          <span class="inv-rarity" style="color:#${meta.color.toString(16).padStart(6, '0')}">${meta.rarityLabel}</span>
        </div>
        <div class="inv-name">${meta.name}</div>
        <div class="inv-desc">${meta.desc}</div>
        <div class="inv-bottom">
          <span class="inv-credits">${meta.credits} CR</span>
          <span class="inv-tag">${meta.research ? 'RESEARCH' : meta.type}</span>
          <button class="inv-drop" data-drop="${item.uid}">DROP</button>
        </div>`
      grid.appendChild(card)
    }
  }

  showLog(source, title, body) {
    this.el['log-source'].textContent = source || 'TERMINAL // UNKNOWN'
    this.el['log-title'].innerHTML = title || 'ARCHIVE <b>ENTRY</b>'
    this.el['log-body'].innerHTML = (body || '').replace(/<warn>/g, '<span class="warn">').replace(/<\/warn>/g, '</span>')
    this.showScreen('log')
  }

  setQualityLabel(quality) {
    this.el['btn-title-quality'].textContent = `GRAPHICS: ${quality.toUpperCase()}`
    for (const b of this.qualityButtons) b.classList.toggle('active', b.dataset.quality === quality)
  }

  setAudioLabel(enabled) {
    this.el['btn-title-audio'].textContent = `AUDIO: ${enabled ? 'ON' : 'OFF'}`
    const pauseBtn = this.el['btn-pause-audio']
    pauseBtn.innerHTML = `AUDIO <b>${enabled ? 'ON' : 'OFF'}</b>`
  }

  showComplete({ time, research, credits, items }) {
    this.el['complete-time'].textContent = fmtTime(time)
    this.el['complete-research'].textContent = `${research} / 3`
    this.el['complete-credits'].textContent = String(credits)
    const list = this.el['complete-list']
    list.innerHTML = ''
    for (const item of items) {
      const row = document.createElement('div')
      row.className = 'complete-row'
      row.innerHTML = `<span>${item.meta.name}${item.meta.research ? ' [RESEARCH]' : ''}</span><span>+${item.meta.credits} CR</span>`
      list.appendChild(row)
    }
    this.showScreen('complete')
  }

  setMobileLookHintHidden(hidden) {
    if (hidden) document.body.classList.add('has-looked')
  }

  setPromptKeyForMobile() {
    this.el['prompt-key'].textContent = this.mobile ? 'USE' : 'E'
  }
}

import * as THREE from 'three'
import { Outpost, PATROLS, isBlocked } from './world/outpost.js'
import { Operative, ThirdPersonCamera } from './player.js'
import { SecurityRobot } from './enemies.js'
import { LootSystem, ITEMS } from './loot.js'
import { UI } from './ui.js'
import { AudioEngine } from './audio.js'

/* ========================================================================== */
/* Boot                                                                       */
/* ========================================================================== */
const ui = new UI()
const audio = new AudioEngine()

function readStored(key) {
  try { return localStorage.getItem(key) } catch { return null }
}
function store(key, value) {
  try { localStorage.setItem(key, value) } catch { /* ignore */ }
}

function detectQuality() {
  const saved = readStored('ls09_quality')
  if (saved === 'low' || saved === 'medium' || saved === 'high') return saved
  const coarse = window.matchMedia('(pointer: coarse)').matches
  if (coarse) {
    const mem = navigator.deviceMemory || 4
    return mem <= 4 ? 'low' : 'medium'
  }
  return 'high'
}

let quality = detectQuality()
const isMobile = ui.mobile

const canvas = document.getElementById('game')
let renderer
try {
  renderer = new THREE.WebGLRenderer({
    canvas,
    antialias: quality !== 'low',
    powerPreference: 'high-performance',
    alpha: false,
    stencil: false,
  })
} catch (err) {
  ui.setError('WebGL could not be initialized on this device. Try enabling hardware acceleration or a different browser.')
  throw err
}

renderer.outputColorSpace = THREE.SRGBColorSpace
renderer.toneMapping = THREE.ACESFilmicToneMapping
renderer.toneMappingExposure = 1.18
renderer.shadowMap.enabled = quality !== 'low'
renderer.shadowMap.type = THREE.PCFShadowMap
renderer.setPixelRatio(quality === 'high' ? Math.min(window.devicePixelRatio || 1, 2) : quality === 'medium' ? Math.min(window.devicePixelRatio || 1, 1.5) : 1)
renderer.setSize(window.innerWidth, window.innerHeight)

const scene = new THREE.Scene()
scene.background = new THREE.Color(0x03080d)
scene.fog = new THREE.FogExp2(0x06121a, 0.026)

const camera = new THREE.PerspectiveCamera(62, window.innerWidth / window.innerHeight, 0.08, 130)
camera.rotation.order = 'YXZ'

ui.setLoading(0.18, 'INITIALIZING RECOVERY SUIT')
const world = new Outpost(scene, quality)
ui.setLoading(0.52, 'OUTPOST GEOMETRY ONLINE')

const player = new Operative(scene)
player.teleport(0, 6.4, Math.PI)
const cam = new ThirdPersonCamera(camera)
cam.yaw = 0

const loot = new LootSystem(scene, world)

const robots = [
  new SecurityRobot(scene, { name: 'K-7', start: { x: -6.5, z: -5 }, patrol: PATROLS.lab, visionRange: 13, fov: 76 }),
  new SecurityRobot(scene, { name: 'K-9', start: { x: 0, z: -13.5 }, patrol: PATROLS.storage, visionRange: 12.5, fov: 74 }),
]
const enemies = robots

ui.setLoading(0.82, 'SECURITY UNITS DEPLOYED')
ui.setAudioLabel(audio.enabled)
ui.setQualityLabel(quality)
ui.setPromptKeyForMobile()

/* ========================================================================== */
/* Game state                                                                 */
/* ========================================================================== */
let state = 'menu' // menu | playing | paused | inventory | log | dead | complete
let elapsed = 0
let menuTime = 0
let lastFrame = performance.now() / 1000
let inventory = []
let hasKeycard = false
let dataCredits = 0
let lastPrompt = null
let currentHide = null
let researchReadyNotified = false
let lastAlertToast = -10
let pendingToast = null
const terminalsRead = new Set()
const extraction = { active: false, elapsed: 0, duration: 12, lastTick: -1 }
const input = { x: 0, z: 0, sprint: false }
const keys = new Set()
let mobileSprint = false
let joystick = { x: 0, z: 0, active: false, pointerId: null }
let lookPointer = { id: null, x: 0, y: 0 }
let dragging = false
let dragX = 0, dragY = 0

const tmpVec = new THREE.Vector3()
const tmpDir = new THREE.Vector3()

/* ========================================================================== */
/* Quality                                                                    */
/* ========================================================================== */
function applyQuality(q, announce = false) {
  quality = q
  const dpr = q === 'high' ? Math.min(window.devicePixelRatio || 1, 2)
    : q === 'medium' ? Math.min(window.devicePixelRatio || 1, 1.5) : 1
  renderer.setPixelRatio(dpr)
  renderer.setSize(window.innerWidth, window.innerHeight)
  renderer.shadowMap.enabled = q !== 'low'
  world.setQuality(q)
  // trim the realtime light count on low-end hardware
  if (world.labFill) world.labFill.visible = q !== 'low'
  if (world.researchLight) world.researchLight.visible = q !== 'low'
  ui.setQualityLabel(q)
  store('ls09_quality', q)
  if (announce) {
    ui.toast('GRAPHICS PROFILE', `${q.toUpperCase()} — ${q === 'low' ? 'battery saver' : q === 'medium' ? 'balanced' : 'full detail'}`, 'rare')
  }
}
applyQuality(quality)

/* ========================================================================== */
/* Robot wiring                                                               */
/* ========================================================================== */
for (const robot of robots) {
  robot.onAttack = (r, damage) => {
    if (state !== 'playing' || player.hidden) return
    const died = player.takeDamage(damage)
    ui.flashDamage()
    cam.addShake(0.15)
    audio.damage()
    if (died) die()
  }
  robot.onStateChange = (r, next) => {
    if (state !== 'playing') return
    if (next === 'chase') {
      audio.alert()
      if (elapsed - lastAlertToast > 4) {
        lastAlertToast = elapsed
        ui.toast('DETECTION // UNIT ' + r.name, 'Break line of sight or conceal yourself', 'warn')
      }
      // nearby unit receives the alert
      for (const other of robots) {
        if (other === r) continue
        const d = other.position.distanceTo(r.position)
        if (d < 28) other.alertTo(player.position, true)
      }
    }
  }
}

/* ========================================================================== */
/* Interaction helpers                                                        */
/* ========================================================================== */
function researchCount() {
  return inventory.filter((i) => i.meta.research).length
}

function inventoryCredits() {
  return inventory.reduce((sum, i) => sum + i.meta.credits, 0)
}

function totalCredits() {
  return inventoryCredits() + dataCredits
}

function refreshInventoryUI() {
  ui.renderInventory(inventory, researchCount(), totalCredits(), hasKeycard, state === 'inventory')
}

function nearestInteractable() {
  let best = null
  let bestD = Infinity
  for (const it of world.interactables) {
    if (it.active === false) continue
    if (it.kind === 'container' && it.opened) continue
    if (it.kind === 'door' && world.researchDoor && world.researchDoor.unlocked) continue
    const dx = it.x - player.position.x
    const dz = it.z - player.position.z
    const d2 = dx * dx + dz * dz
    if (d2 > it.radius * it.radius) continue
    if (d2 < bestD) { bestD = d2; best = it }
  }
  return best
}

function promptLabelFor(it) {
  if (!it) return ''
  if (it.kind === 'extraction') {
    return researchCount() >= 3 ? 'Initiate extraction' : `Extraction locked — ${researchCount()} / 3 research`
  }
  if (it.kind === 'door') {
    return hasKeycard ? 'Unlock research wing' : 'Sealed — security keycard required'
  }
  if (it.kind === 'loot') {
    const meta = ITEMS[it.id.split('|')[0]]
    void meta
  }
  return it.label
}

function handleInteract() {
  if (state !== 'playing' || !player.alive) return
  if (player.hidden) {
    leaveHide()
    return
  }
  const it = lastPrompt
  if (!it) return
  const count = researchCount()

  if (it.kind === 'loot') {
    tryPickup(it.id)
  } else if (it.kind === 'hide') {
    enterHide(it)
  } else if (it.kind === 'terminal') {
    openTerminal(it)
  } else if (it.kind === 'container') {
    openContainer(it)
  } else if (it.kind === 'door') {
    if (world.researchDoor && world.researchDoor.unlocked) return
    if (hasKeycard) {
      world.unlockResearchDoor()
      audio.unlock()
      cam.addShake(0.05)
      ui.toast('CLEARANCE ACCEPTED', 'Research wing unlocked — Level 4 access', 'good', 3600)
      ui.setPrompt('', 'E', false)
      lastPrompt = null
    } else {
      audio.ui(false)
      ui.toast('ACCESS DENIED', 'Security keycard required. Search the storage bay.', 'warn', 3600)
    }
  } else if (it.kind === 'extraction') {
    if (extraction.active) return
    if (count >= 3) startExtraction()
    else {
      audio.ui(false)
      ui.toast('EXTRACTION DENIED', `${count} / 3 research assets validated. Recover ${3 - count} more.`, 'warn', 3600)
    }
  }
}

function tryPickup(uid) {
  if (inventory.length >= 6) {
    audio.ui(false)
    ui.toast('FIELD PACK FULL', 'Open the pack (TAB) and discard an item to free a slot.', 'warn', 4000)
    return
  }
  const item = loot.pickup(uid)
  if (!item) return
  const meta = item.meta
  const entry = { uid: item.uid, metaId: item.metaId, meta }
  inventory.push(entry)
  if (meta.battery) {
    const before = player.battery
    player.rechargeBattery(meta.battery)
    if (player.battery > before) {
      ui.toast('BATTERY RECHARGED', `+${Math.round(player.battery - before)}% suit lamp capacity`, 'good', 3200)
    }
  }
  audio.pickup(meta.rarity)
  ui.toast(`ACQUIRED // ${meta.name.toUpperCase()}`, `${meta.rarityLabel} • ${meta.type} • +${meta.credits} CR`, meta.rarity, 3600)
  refreshInventoryUI()
  ui.setPrompt('', 'E', false)
  lastPrompt = null
  if (researchCount() >= 3 && !researchReadyNotified) {
    researchReadyNotified = true
    setTimeout(() => {
      if (state === 'playing') {
        ui.toast('EXTRACTION READY', 'Research validated. Proceed to extraction pad 09.', 'good', 4400)
        audio.unlock()
      }
    }, 700)
  }
}

function dropItem(uid) {
  if (state !== 'inventory') return
  const idx = inventory.findIndex((i) => i.uid === uid)
  if (idx < 0) return
  const [entry] = inventory.splice(idx, 1)
  const fx = Math.sin(player.physics.yaw)
  const fz = Math.cos(player.physics.yaw)
  const x = player.position.x + fx * 0.7
  const z = player.position.z + fz * 0.7
  loot.spawnDropped(entry.metaId, x, z)
  audio.ui(false)
  ui.toast('ITEM DISCARDED', `${entry.meta.name} dropped at your position`, '', 2600)
  refreshInventoryUI()
}

function openContainer(it) {
  if (it.opened) return
  it.opened = true
  world.openContainer(it.id)
  audio.container()
  const lootType = it.loot
  if (lootType === 'keycard') {
    hasKeycard = true
    audio.unlock()
    ui.toast('SECURITY KEYCARD', 'Level 4 research clearance acquired', 'good', 4200)
  } else if (lootType === 'medkit') {
    player.heal(45)
    ui.toast('MEDKIT RECOVERED', '+45 suit integrity', 'good', 3200)
  } else if (lootType === 'battery') {
    player.rechargeBattery(100)
    ui.toast('BATTERY REPLACED', 'Suit lamp fully charged', 'good', 3200)
  } else if (lootType === 'credits') {
    dataCredits += 120
    ui.toast('CREDITS RECOVERED', '+120 CR', 'uncommon', 3200)
  }
  refreshInventoryUI()
}

function openTerminal(it) {
  state = 'log'
  releasePointerLock()
  audio.setPaused(true)
  audio.terminal()
  ui.setPrompt('', 'E', false)
  lastPrompt = null
  if (!terminalsRead.has(it.id)) {
    terminalsRead.add(it.id)
    dataCredits += 25
    pendingToast = { title: 'DATA RECOVERED', sub: '+25 CR // archive copy secured', rarity: 'rare' }
  }
  ui.showLog(it.source, it.title, it.body)
  refreshInventoryUI()
}

/* ========================================================================== */
/* Hiding                                                                     */
/* ========================================================================== */
function enterHide(it) {
  if (player.hidden) return
  currentHide = it
  player.setHidden(true, it.hideType)
  player.teleport(it.hidePos.x, it.hidePos.z, it.hidePos.yaw + Math.PI)
  cam.yaw = it.hidePos.yaw
  cam.pitch = 0.04
  cam.initialized = false
  audio.hide()
  ui.setHidden(true)
  ui.setPrompt('', 'E', false)
  ui.toast('CONCEALED', 'Enemy visual contact blocked', 'good', 2200)
  lastPrompt = null
}

function leaveHide() {
  if (!player.hidden || !currentHide) return
  const yaw = cam.yaw
  const fx = -Math.sin(yaw)
  const fz = -Math.cos(yaw)
  let x = player.position.x + fx * 0.95
  let z = player.position.z + fz * 0.95
  if (isBlocked(world.colliders, x, z, 0.42)) {
    x = player.position.x + fx * 0.35
    z = player.position.z + fz * 0.35
  }
  if (isBlocked(world.colliders, x, z, 0.42)) {
    x = player.position.x
    z = player.position.z
  }
  player.setHidden(false)
  player.teleport(x, z, yaw + Math.PI)
  cam.yaw = yaw
  cam.pitch = 0.22
  cam.initialized = false
  currentHide = null
  audio.hide()
  ui.setHidden(false)
  ui.toast('LEFT COVER', 'You are exposed again', '', 1800)
}

/* ========================================================================== */
/* Extraction                                                                 */
/* ========================================================================== */
function startExtraction() {
  extraction.active = true
  extraction.elapsed = 0
  extraction.lastTick = 12
  researchReadyNotified = true
  world.setExtractionActive(true)
  audio.extractionStart()
  ui.toast('EXTRACTION INITIATED', 'Hold position on pad 09 for 12 seconds', 'good', 4200)
  if (isMobile) {
    ui.setPrompt('', 'USE', false)
  }
  lastPrompt = null
}

function cancelExtraction(reason) {
  extraction.active = false
  world.setExtractionActive(false)
  ui.setExtraction(false)
  audio.ui(false)
  ui.toast('EXTRACTION ABORTED', reason, 'warn', 3600)
}

function updateExtraction(dt) {
  if (!extraction.active) return
  extraction.elapsed += dt
  const progress = Math.min(1, extraction.elapsed / extraction.duration)
  const remaining = Math.max(0, extraction.duration - extraction.elapsed)
  const dist = Math.hypot(player.position.x - world.extractionX, player.position.z - world.extractionZ)
  const padX = 0
  const padZ = 22.1
  const padDist = Math.hypot(player.position.x - padX, player.position.z - padZ)
  void dist

  if (padDist > 7.2) {
    cancelExtraction('You left the extraction zone.')
    return
  }
  if (progress >= 1) {
    extraction.active = false
    world.setExtractionActive(false)
    ui.setExtraction(false)
    completeMission()
    return
  }
  ui.setExtraction(true, progress, remaining)
  const sec = Math.ceil(remaining)
  if (sec !== extraction.lastTick) {
    extraction.lastTick = sec
    audio.tick(sec <= 3)
  }
  if (extraction.elapsed > 3.2 && !extraction.alerted) {
    extraction.alerted = true
    let nearest = null
    let best = Infinity
    for (const r of robots) {
      const d = Math.hypot(r.position.x, r.position.z - 22.1)
      if (d < best) { best = d; nearest = r }
    }
    if (nearest) {
      nearest.alertTo({ x: 0, z: 22.1 }, true)
      ui.toast('SECURITY ALERT', 'A unit is moving toward the extraction pad', 'warn', 3600)
    }
  }
}

/* ========================================================================== */
/* End states                                                                 */
/* ========================================================================== */
function die() {
  if (state === 'dead') return
  state = 'dead'
  releasePointerLock()
  extraction.active = false
  world.setExtractionActive(false)
  ui.setExtraction(false)
  ui.setPrompt('', 'E', false)
  player.alive = false
  player.setFlashlight(false)
  audio.setPaused(true)
  audio.death()
  ui.showDead()
}

function completeMission() {
  state = 'complete'
  releasePointerLock()
  audio.setPaused(true)
  ui.setPrompt('', 'E', false)
  ui.setExtraction(false)
  const credits = totalCredits() + 300
  ui.showComplete({
    time: elapsed,
    research: researchCount(),
    credits,
    items: inventory.slice(),
  })
  audio.complete()
}

/* ========================================================================== */
/* Objective + HUD                                                            */
/* ========================================================================== */
function objectiveInfo() {
  if (extraction.active) {
    return {
      text: 'Hold position for extraction', sub: 'EXTRACTION IN PROGRESS', label: 'EXTRACTION',
      target: { x: 0, y: 1.4, z: 22.1 }, progress: researchCount() / 3,
    }
  }
  if (researchCount() >= 3) {
    return {
      text: 'Reach the extraction pad', sub: 'RESEARCH VALIDATED — PAD 09 // SOUTH', label: 'EXTRACTION',
      target: { x: 0, y: 1.4, z: 22.1 }, progress: 1,
    }
  }
  const has = (id) => inventory.some((i) => i.metaId === id)
  let target = null
  let text = 'Recover remaining research assets'
  let sub = `${researchCount()} / 3 RESEARCH ITEMS`
  let label = 'RESEARCH'
  if (!has('doc-lab')) {
    text = 'Recover Dr. Voss’s field log'
    sub = 'LAB-01 // CENTRAL'
    label = 'RESEARCH LOG'
    const anchor = world.lootAnchors['doc-lab']
    target = { x: anchor.x, y: anchor.y, z: anchor.z }
  } else if (!hasKeycard) {
    text = 'Recover the security keycard'
    sub = 'STORAGE 02 // CARGO CRATE'
    label = 'SECURITY CARD'
    const it = world.interactables.find((i) => i.kind === 'container' && i.id === 'storage-keycard')
    target = it ? { x: it.x, y: 1.0, z: it.z } : { x: 0, y: 1, z: -23 }
  } else if (!has('doc-storage')) {
    text = 'Recover the signal analysis'
    sub = 'STORAGE 02 // ARCHIVE'
    label = 'RESEARCH LOG'
    const anchor = world.lootAnchors['doc-storage']
    target = { x: anchor.x, y: anchor.y, z: anchor.z }
  } else if (!has('module-research')) {
    text = 'Recover Project ECHO’s quantum core'
    sub = 'RESEARCH WING // LOCKED'
    label = 'QUANTUM CORE'
    const anchor = world.lootAnchors['module-research']
    target = { x: anchor.x, y: anchor.y, z: anchor.z }
  } else {
    const nearest = loot.nearestResearch(player.position.x, player.position.z)
    if (nearest) {
      text = 'Recover remaining research'
      sub = `${researchCount()} / 3 RESEARCH ITEMS`
      target = { x: nearest.anchor.x, y: nearest.anchor.y, z: nearest.anchor.z }
    } else {
      text = 'Return to the extraction pad'
      sub = `${researchCount()} / 3 RESEARCH ITEMS`
      target = { x: 0, y: 1.4, z: 22.1 }
    }
  }
  return { text, sub, label, target, progress: researchCount() / 3 }
}

function updateObjectiveUI() {
  const info = objectiveInfo()
  const dist = info.target ? Math.hypot(info.target.x - player.position.x, info.target.z - player.position.z) : null
  ui.setObjective(info.text, info.sub, dist, info.progress)
  if (!info.target) { ui.setMarker(false); return }
  const t = info.target
  tmpVec.set(t.x, t.y + 0.35, t.z)
  tmpDir.copy(tmpVec).sub(camera.position)
  camera.getWorldDirection(tmpVec)
  if (tmpDir.dot(tmpVec) <= 0.08) {
    ui.setMarker(false)
    return
  }
  const ndc = new THREE.Vector3(t.x, t.y + 0.35, t.z).project(camera)
  let x = (ndc.x * 0.5 + 0.5) * window.innerWidth
  let y = (-ndc.y * 0.5 + 0.5) * window.innerHeight
  const mx = isMobile ? 46 : 70
  const topM = 92
  const botM = isMobile ? 210 : 100
  x = Math.max(mx, Math.min(window.innerWidth - mx, x))
  y = Math.max(topM, Math.min(window.innerHeight - botM, y))
  ui.setMarker(true, x, y, dist, info.label)
}

function updateInteractionUI() {
  if (extraction.active) {
    ui.setPrompt('', 'E', false)
    lastPrompt = null
    return
  }
  if (player.hidden) {
    ui.setPrompt('Leave concealment', isMobile ? 'USE' : 'E', true)
    lastPrompt = null
    return
  }
  const it = nearestInteractable()
  lastPrompt = it
  if (!it) {
    ui.setPrompt('', 'E', false)
    return
  }
  let label = promptLabelFor(it)
  if (it.kind === 'loot') {
    const lootItem = loot.items.get(it.id)
    if (lootItem) label = `Collect ${lootItem.meta.name} — ${lootItem.meta.rarityLabel}`
