  world.update(dt, player.position, robots)
  loot.update(dt, elapsed)
  for (const r of robots) r.update(dt, player, world, true)
  updateCamera(dt)
  updateExtraction(dt)
  updateHUD(dt)

  if (player.health <= 0 && state === 'playing') die()
}

